  "posts": "东莞市公办中小学（公益一类）教师，含市直属学校及镇街园区属学校，覆盖中小学大部分学科",
  "count": "392（共285个职位，涵盖语文、数学、英语、道德与法治、思想政治、历史、地理、生物、化学、物理、音乐、体育与健康、美术、心理健康、信息科技、科学、特殊教育、综合实践等学科）",
  "staffing": "事业编",
  "enroll": "2026年1月7日-1月14日14:00（网上报名，网址 https://www.qgsydw.com/xxywzlzt/bmzt/305）",
  "exam": "报名—资格初审—笔试（学科知识，2026年1月16日）—资格复审—面试/考核；音乐、体育、信息科技等岗位另加专业技能考核",
  "condition": "招聘对象：①纳入国内普通高校统一招生计划、2025年9月—2026年8月期间毕业，具有普通高等院校本科学历及学士学位（含）以上的毕业生（非在职学历）；②2025年2月—2026年1月期间毕业的国（境）外院校本科及以上毕业生（非在职学历），须2026年8月31日前取得并提供教育部留学服务中心认证结果。毕业时间以毕业证书和学位证书落款时间为准；在境内就读的中外合作办学2026年本科应届毕业生须2026年8月31日前取得毕业证书、2026年12月31日前取得学位证书；其余2026年应届毕业生须2026年8月31日前取得毕业证书、学位证书；除国内普通院校未毕业的应届毕业生外，其余报考人员须于报名时取得相应毕业证书、学位证书。学历学位：本科及以上并取得学士及以上学位，学位证书须与岗位要求学历层次的毕业专业对应；全部研究生岗位要求本科和硕士研究生（或硕士研究生和博士研究生）毕业专业均符合《专业对照表》要求。专业：所学专业须与岗位要求的学历学位层次相对应并符合《岗位专业对照表》；研究生阶段所学专业为学科教学、课程与教学论、教育学等，专业方向与岗位要求一致的视为符合，无注明方向者报考义务教育阶段（初中、小学）语文、数学、英语教师岗位可视为符合；专业未列入目录的可按相近专业报考，须提交毕业证书（或就业推荐表）、教务处盖章的专业课程成绩单、院校课程对比说明及设置专业依据材料，经审定后方可。教师资格：须取得岗位对应专业和层次及以上教师资格（如小学数学教师岗位须小学及以上层次数学教师资格；初中英语岗位须初中及以上层次英语教师资格；义务教育语文岗位须初中及以上层次语文教师资格；高中物理岗位须高中及以上层次物理教师资格）；符合以下三种情形之一者报名时提交承诺书可暂不提供教师资格证明：①取得博士研究生学历者最后取得时间为2026年12月；②符合免试认定教师资格的2026年师范毕业生为2026年8月；③2026年应届毕业生且已通过岗位对应专业和层次教师资格笔试者为2026年8月；未按时取得者取消聘用资格。年龄：具有博士研究生学历学位者40周岁及以下（1985年1月及以后出生），其他人员38周岁及以下（1987年1月及以后出生）。户籍：不限。岗位附加条件：英语教师岗位——高中英语须英语专业八级（2026年英语本科毕业生可提供承诺书，入职前取得）或雅思7.0分及以上或托福105分及以上；义务教育、初中和小学英语岗位须英语专业四级及以上或雅思7.0分及以上或托福100分及以上；语文教师岗位须普通话水平测试二级甲等及以上；音乐、体育、美术和信息科技教师岗位注明方向的须提供大学毕业专业、必修课程或获奖证书等方向证明材料。其他：服务期满且考核合格后2年内的服务基层项目人员（大学生村官、三支一扶、西部计划、山区计划等）可以毕业生身份报考；高校毕业生士兵退役后1年内可视同当年应届毕业生；符合报考条件的东莞市生源公费师范生可不受报考岗位学历学位要求限制，但专业须相符；东莞在职在编教职员和已获得东莞市教育局公开招聘拟聘资格（入围体检）的人员不在本次招聘范围内。",
