  "condition": "招聘对象：取得国民教育系列本科及以上或经教育部留学服务中心认定的国（境）外本科及以上学历，并取得符合本次招聘要求的专业技术职称的人员；招聘岗位对学位有要求的，学士及以上学位证书须与报考岗位要求学历层次的毕业专业对应（使用职称证书上的专业或特长专项报考普通教职员岗位的除外）。分为三类：①高层次人才（具有正高级、副高级专业技术职称或博士研究生学历学位）；②急需紧缺人才（符合我市教育系统急需紧缺学科相关要求，具有岗位对应职称且满足学历、年龄、专业或获奖要求）；③普通教职员（符合中小学校教职员任职资格条件，取得岗位要求的学历学位和专业技术职称）。年龄：报考普通教职员岗位40周岁及以下（1985年4月30日及以后出生），其中博士研究生以及具备教师系列中级及以上职称者45周岁及以下；年龄计算截至公告发布之日。专业：普通教职员岗位须符合《普通教职员岗位专业对照表》，研究生阶段所学专业为学科教学、课程与教学论、教育学等，专业方向与岗位要求一致的视为符合，无注明方向者报考义务教育阶段语文、数学、英语岗位可视为符合；取得岗位对应学科初级（助理级）及以上教师系列职称并有2学年该学科中小学校相应学段教学经历（截至2026年8月）的可视同专业相符；普通高校体育统考生/特招生、艺考生其特长专项与岗位专业相符并可提供入学证明材料的可报考；专业未列入目录的可按相近专业报考，须提交课程成绩单、院校课程对比说明及设置专业依据。职称：须于2026年4月30日前取得岗位相应级别及以上职称（已公示未发证者可持公示材料报考，须2026年9月30日前取得证书）；距本公告发布之日起毕业满1年且未满3年（2023年4月—2025年4月期间毕业）的全日制研究生报考普通教职员中的教师初级岗位时可暂不要求职称，但不得报考中级岗位。教师资格：须取得岗位对应专业和层次及以上教师资格（如小学数学教师岗位须小学及以上层次数学教师资格；初中英语岗位须初中及以上层次英语教师资格；义务教育语文岗位须初中及以上层次语文教师资格；高中物理岗位须高中及以上层次物理教师资格）；报考科学教师岗位者取得《岗位专业对照表》中对应专业（相符和相近）的教师资格证可视同符合专业要求；博士研究生报考时可暂不提供教师资格证明，但须于2027年6月30日前取得教师资格证。户籍：不限。其他：音乐、体育、美术和信息科技教师岗位注明方向的须提供大学专业、必修课程、获奖证书或资格证书等材料，获奖证书须为县区级及以上（含不设县区的地级市下辖镇街、园区），有名次者须前3名（省级及以上前8名）；学历学位、职称证书、荣誉材料须真实有效。不得报考情形包括：受过刑事处罚、被开除公职或党籍、近两年在公务员/事业单位招考中被认定有舞弊行为、被列为失信联合惩戒对象、聘用后构成回避关系、已签订广东省公费定向培养中小学教师协议书且尚未履行约定等。",
