  "condition": "招聘对象分两类。一、毕业生：纳入国内普通高校统一招生计划、2025年—2026年8月31日期间毕业的具有普通高等院校本科学历及学士学位（含）以上毕业生（非在职学历）；以及同期毕业的国（境）外院校本科及以上毕业生（非在职学历），须2026年8月31日前取得并提供教育部留学服务中心认证结果。二、社会人员：幼儿园教师须为普通高校本科（学士）及以上学历，或第一学历为中等幼儿师范学校及以上且持有幼儿园教师中级职称及以上（特别优秀者可适当放宽职称要求）；中小学教师须为普通高校本科（学士）及以上学历；教辅人员须为本科（学士）及以上学历。基本条件：具有中华人民共和国国籍，具备良好的思想品质和职业道德，遵纪守法、品行端正；遵守宪法和法律，拥护中国共产党领导和社会主义制度；具有良好的政治素质和品行；身体健康，具有适应岗位要求的身体条件和心理条件；具备招聘岗位要求的专业和技能条件；符合本公告及《岗位表》所规定的资格条件。不得报考情形：受过刑事处罚；被开除公职或开除中国共产党党籍，或受其他影响录用处分正在处分期内（截至报名截止日）；近两年在各级公务员、事业单位招考中被认定有舞弊等违反录用纪律行为；因涉嫌违法违纪正在接受审计、纪律审查或涉嫌犯罪司法程序尚未终结；被依法列为失信联合惩戒对象；聘用后即构成回避关系；肄业生、现役军人等。待遇：幼儿园教师年薪13-15万元，教辅人员年薪9-13万元。岗位具体学科、教师资格证及专业要求详见《岗位表》，公告正文未逐条列明。",
