  "posts": "塘厦镇属公办中小学临聘教师19名（具体岗位见《岗位表》，由镇教育管理中心统筹）",
  "count": "19",
  "staffing": "合同制",
  "enroll": "即日起至2026年1月25日16:00（填写问卷星并将报名材料打包发至岗位表指定邮箱）",
  "exam": "面试考核分两轮：综合素质评价（体育、美术、心理教师岗位为实操技能展示）+试讲（从综合素质评价达标人员中按1:3确定入围，备课30分钟、试讲8分钟）；2026年1月29日上午7:30签到、8:00开考，地点塘厦第二实验小学；考核成绩百分制，达标线80分；总成绩=综合素质评价×40%+试讲×60%",
  "condition": "招聘对象：符合报考条件的应届毕业生和社会人员；在塘厦镇民办学校工作且在有效合同期内的教师报考须提供所在学校签署的同意报考证明。应届毕业生：指在2025年6月至2026年1月期间取得普通高等院校本科学历及学士学位（含）以上的、纳入国内普通高校统一招生计划的毕业生（非在职学历）和教育部承认学历学位的国（境）外院校毕业生。社会人员：应届毕业生外符合报考条件的人员。年龄：原则上不超过40周岁，特别优秀的可放宽到45周岁。基本条件：具有中华人民共和国国籍，具备良好的思想品质和职业道德，遵纪守法、品行端正；遵守中华人民共和国宪法和法律；身体健康，具有适应岗位要求的身体条件；具备招聘岗位所要求的其他条件；法律法规规定的其他条件。教师资格证要求：持有相应岗位学段及以上学段学科的教师资格证。专业相符要求满足下列条件之一：①所学本科及以上学历专业相符（普通高校本科/研究生专业与岗位专业相符，具体见《岗位表》；普通高考招聘特长生的特长专业与岗位专业相符；取得两个本科及以上专业毕业的其中之一相符，学位类别不能作为专业类别报考；高层次学历可以报考要求低层次学历的岗位）；②职称与专业相符（中级及以上职称专业学科与岗位专业相符；初级职称专业学科与岗位专业相符且具有相关专业学科2年及以上教学经历，以合同和社保材料证明为准）；③专业相近（所学专业含海外学历学位与招聘岗位要求专业相近但未列入岗位要求专业范围，所学专业主要课程与岗位要求专业主要课程超过一半基本一致的，可填写毕业证书专业名称并提交成绩表报考，审核认定为相近专业后可通过）。研究生阶段所学专业为学科教学、课程与教学论、教育学的，其专业研究方向与报考教师岗位一致的视为符合要求。不得报考情形：有违法犯罪记录；受行政开除处分未满五年或受其他处分正在处分期内；近两年内在各级机关事业单位招录（聘）考试、体检或考察中存在违纪行为；因涉嫌违法违纪正在接受审计、纪律审查或涉嫌犯罪司法程序尚未终结；被依法依规列为失信联合惩戒对象；聘用后即构成回避关系；肄业生、现役军人和其他规定不能报考的人员；违反师德行为并影响恶劣；法律法规规定不宜聘用为事业单位工作人员的其他情形。待遇：执行塘厦镇中小学聘用教师工资待遇标准，年薪13.5万元起（含五险一金）；拟聘人员须于2026年3月份入职，试用期1个月，聘期一年，聘期结束经考核优秀者在学校岗位空缺时可优先续聘。",
