  "condition": "已在公告中明确的报考条件：①专业匹配要求——本科及以上学历所学专业必须要与岗位学科专业对应，具体标准参照《广东省2026年考试录用公务员专业参考目录》和《东莞市教育局公开招聘事业编制教师岗位专业对照表》。②教师资格证书要求——须持有与授课学段一致或更高学段教师资格证书（教资专业不限），无证人员一律不得录用。③其他要求——自觉遵守国家各项法律法规、教育行业管理规范及校内教学管理制度，具备良好的政治素养、师德师风与职业操守，恪守教师职业行为十项准则；身心健康，无传染性疾病、精神类疾病及其他影响正常教育教学工作的身心疾病，能够完全适配学校一线课堂教学、课后辅导、学情答疑等全流程教学工作强度；品行端正、作风正派，无违法犯罪记录、无师德失范处分记录、无行业从业黑名单记录、无任何在校及公职系统违纪违规处分记录；坚持立德树人，关爱全体在校学生，尊重学生人格与个体差异，严禁体罚、变相体罚及言语羞辱学生。④不得报考人员：现役军人、在读的非2026年毕业生；尚未解除纪律处分或者正在接受纪律审查、监察调查的人员，因犯罪受过刑事处罚的人员和被开除公职的人员，或者涉嫌违法犯罪正在接受调查的人员；近两年内在全国机关、事业单位招录（聘）考试、体检或考察中存在违纪行为的人员；法律法规和规章规定不宜报名的其他情形。报名材料须提交居民身份证、学历学位证书及学信网认证、教师资格证及核验结果截图、职称证（如有）、个人荣誉或获奖（如有）、近期生活照1张、5-10分钟个人试讲视频。年龄上限、各学科岗位人数分布、薪酬待遇等其他条件公告未明确。",
