  "condition": "招聘对象：普通高等教育取得本科以上学历及学士以上学位的2026年应届毕业生（即2025年9月1日至2026年8月31日期间毕业的应届毕业生，以毕业证书落款日期为准）；博士研究生（非在职）可放宽毕业年限（即2026年8月31日前毕业的毕业生）。专业院校毕业并有特殊专长的优秀毕业生（专业院校指音乐、美术、体育等方面的专业院校）亦可报考。思想品德：具有中华人民共和国国籍，拥护中国共产党的领导，热爱教育事业，为人师表，遵纪守法，乐于奉献。教师资格：具有相应的教师资格。学历（学位）：须为普通高等院校本科以上学历、学士以上学位（具体要求见岗位表；部分岗位要求研究生学历、硕士及以上学位）。专业：应聘人员的所学专业需与岗位（学科）要求一致，具体参考岗位表及《广东省2026年考试录用公务员专业参考目录》；专业未列入岗位要求范围且专业参考目录无法查询到一致专业名称，但与招聘岗位（学科）专业相近的，需提供学历学位证书、成绩单及毕业院校出具的《关于所学专业与岗位所需专业相近的证明》，国（境）外高校无法开具相似证明的须提供学历学位证书（如有）、成绩单和课程相近说明（须手写签名）及专业机构出具的中文翻译件，由招聘单位审定是否专业相似；学科教学、小学教育、课程与教学论等专业，如就业推荐表或成绩单上的专业名称无培养方向，须提供院校出具的专业方向一致证明；若所学专业与招聘岗位（学科）要求不一致，但已取得与招聘岗位相应学段和学科的教师资格证（须通过系统上传教师资格证书），也可报考。身体状况：身体健康，符合《广东省教师资格申请人员体格检查标准（2013年修订）》。聘用：纳入顺德区教育事业单位人员编制；拟聘人员要于2026年8月31日前取得岗位（学科）招聘条件要求的学历、学位证书；国（境）外高校毕业生要于2026年8月31日前取得学位并完成教育部中国留学服务中心境外学历、学位认证，否则取消聘用资格。年龄上限公告正文未明确列出。不得报名人员：区内公办在编教师；受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；法律、法规规定的其他情形。",
