  "condition": "招聘对象分为毕业生和社会人员两类，各岗位招聘对象要求详见《广东省佛山市南海区教育系统2026-2027学年度面向社会公开招聘教师岗位表》。毕业生：2025年1月1日—2026年8月31日期间毕业的，纳入普通高等院校统一招生计划的普通高等院校毕业生（非在职）以及教育部承认学历学位的国（境）外院校的毕业生（非在职），含2025、2026届符合公费师范生履约任教有关要求的公费师范生。社会人员：除毕业生外其他符合条件的人员。基本条件：具有中华人民共和国国籍，拥护中华人民共和国宪法，拥护中国共产党领导和社会主义制度；遵纪守法，具有良好的政治素质和道德品行，具有正常履行职责的身体条件、心理素质和符合职位要求的工作能力。学历：具有国家承认的本科以上学历；以毕业生身份报考的须同时取得与岗位相对应的学历及学位证书，以境外学历报考的须取得中国教育部留学服务中心认证的《国（境）外学历学位认证书》；以毕业生身份报考，如报名时未取得与报考岗位相对应的学历及学位证书的，须承诺于2026年8月31日前取得，到期未取得的不予聘用；以社会人员身份报考的须于报名前取得与报考岗位相对应的学历证书并提供证书复印件。专业：专业对口，所学专业与招聘岗位专业要求相符，具体参考《广东省2026年考试录用公务员专业参考目录》；如所学专业未列入目录但主要课程与招聘岗位要求专业的主要课程基本一致的，报名时须提供所学专业课程成绩单（毕业院校盖章）、院校出具的课程对比情况和认定为相近专业的说明，审核通过视为专业对口。年龄：毕业生38周岁以下（博士放宽至43周岁），社会人员45周岁以下。教师资格：具备与招聘岗位相应学段和学科的教师资格证。",
