  "condition": "招聘对象分为毕业生和社会人员两类。毕业生：2025年1月1日—2026年8月31日期间毕业的，纳入普通高等院校统一招生计划的普通高等院校毕业生（非在职）以及教育部承认学历学位的国（境）外院校的毕业生（非在职），含2025、2026届符合公费师范生履约任教有关要求的公费师范生；以本科学历或研究生学历以本科专业报考者，本科期间成绩符合综合排名在本专业前30%，或各学科平均分在80分以上，或平均学分绩点达到3.0以上。社会人员，须符合以下条件之一：1.区外在职教师（不含幼儿园、培训机构）且符合以下条件之一：（1）具有招聘岗位相应学科中级以上教师系列职称；（2）曾获得过招聘岗位相应学科国家级以上奥林匹克竞赛省赛区二等奖以上，或指导学生获得过招聘岗位相应学科国家级以上奥林匹克竞赛省赛区二等奖以上经历的主教练员（主要指导教师）；2.2025年9月1日至今连续在我区任教的专任教师（不含幼儿园、培训机构）。基本条件：具有中华人民共和国国籍，拥护中华人民共和国宪法，拥护中国共产党领导和社会主义制度；遵纪守法，具有良好的政治素质和道德品行，具有正常履行职责的身体条件、心理素质和符合职位要求的工作能力。学历学位：本科以上学历，学士以上学位；其中2026届毕业生须于2026年8月31日前取得与岗位相对应的学历及学位证书，2026届国（境）外毕业生还须取得中国教育部留学服务中心认证的《国（境）外学历学位认证书》；其他报考人员须于报名时取得与岗位相对应的学历及学位证书、《国（境）外学历学位认证书》。专业：专业对口，所学专业与招聘岗位专业要求相符，具体参考《广东省2026年考试录用公务员专业参考目录》。",
