  "title": "2026年佛山市顺德区公办中小学面向社会公开招聘教师公告",
  "posts": "顺德区公办中小学教师，由各镇（街道）教育办及区属学校招聘（容桂、伦教、北滘、乐从、勒流、龙江、均安等）",
  "count": "详见公告（具体见附件1需求表、附件2岗位表）",
  "staffing": "事业编",
  "enroll": "2026年6月5日上午8:30-6月11日下午3:30（登录顺德区教师招聘系统 http://zp.sdedu.net 网络报名，不接受现场报名）；笔试确认时间2026年6月12日上午8:30-下午3:30",
  "exam": "笔试（预计2026年6月13日下午，闭卷、全区统一命题制卷，总分100分、合格线60分，内容为教育学、心理学、教师职业道德规范、基本文化素养和相关教育法律法规等）+现场资格审核+面试（预计6月20日，综合能力测试，总分100分、合格分70分），面试占60%、笔试占40%计算综合总分；具有博士学位的应聘人员系统确认参加笔试后可免笔试直接进入现场资格审核及面试环节，其面试成绩作为综合总分成绩",
  "condition": "招聘对象：社会人员（不含2026年应届毕业生，即2025年9月1日至2026年8月31日期间毕业的应届毕业生，以毕业证书落款日期为准）。思想品德：具有中华人民共和国国籍，拥护中国共产党的领导，热爱教育事业，为人师表，遵纪守法，乐于奉献。教师资格：具有相应的教师资格。年龄：应聘中学教师岗位（学科）的要求40周岁以下（1985年6月5日后出生），应聘小学教师岗位（学科）的要求38周岁以下（1987年6月5日后出生）；具有副高以上职称的年龄可放宽到45周岁（1980年6月5日以后出生）。学历（学位）：须为普通高等院校本科以上学历、学士以上学位（具体要求见附件2岗位表）。专业：应聘人员的所学专业需与岗位（学科）要求一致；如所学专业未列入《广东省2026年考试录用公务员专业参考目录》，可选择专业目录中的相近专业报考，所学专业必修课程须与报考岗位要求专业的主要课程基本一致，需提供学历学位证书、成绩单及毕业院校出具的《关于所学专业与岗位所需专业相近的证明》；若所学专业与招聘岗位专业要求不相符，但已取得的教师资格证所认定的种类和学科与招聘岗位相符，且目前正从事所报考岗位（学科）教学工作的，也可报考（需学校出具证明）；学科教学、小学教育、课程与教学论等专业如就业推荐表或成绩单上的专业名称无培养方向，报考人员需提供院校出具的培养方向证明。职称：社会人员参加工作时间在8年以上的要求具有教师系列中级以上职称。身体状况：身体健康，符合教师资格认定体检标准。其他要求（须符合下列条件之一）：（1）工作满五年的，近五年曾获得县（区）级以上人民政府、教育行政部门颁发的优秀校长或教师荣誉称号；工作不满五年的，曾获得镇（街道）级以上人民政府、教育行政部门（市属、区属学校工作的获得校级以上）颁发的优秀教师荣誉称号；（2）工作满五年的，近五年曾获得县（区）级以上人民政府、教育行政部门、教研室、电教站颁发的教育教学专项性比赛一等奖以上表彰奖励；工作不满五年的，曾获得镇（街道）级以上人民政府、教育行政部门（市属、区属学校工作的获得校级以上）教育教学专项性比赛一等奖以上表彰奖励；（3）具有硕士以上学位者；（4）工作满五年且现于本区学校连续任教满一年的非编教师（即2025年6月5日至今于本区学校任教，需学校提供证明），且近五年曾获得镇（街道）级以上人民政府、教育行政部门颁发的优秀教师证书（含教坛新秀、骨干教师、名师等）或镇（街道）级以上教育教学专项性比赛一等奖以上奖励。聘用：纳入顺德区教育事业单位人员编制。不得报名人员：区内公办在编教师；受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的。",
