  "enroll": "2026年5月28日9:00-6月3日16:00（登录“三水区教师招聘信息管理系统” http://www.ssjyyun.cn/recruit/main/ConvergeIndex 网络报名，每位考生限报一个职位）；笔试确认2026年6月8日10:00至6月10日10:00",
  "exam": "笔试（闭卷，内容为教育学、心理学、基本文化素养、教师职业道德规范和相关教育法律法规等，满分100分、合格分60分，进入面试人数与招聘岗位数比例按不超过3:1确定）—现场资格复审—面试（形式为说课，其中音乐岗位另加考专业试（声乐、钢琴和自选特长表演）；美术岗位另加考专业试（色彩和素描）；体育岗位另加考专业试（200米跑、立定跳远、技能考试），满分100分、合格分70分）；笔试40%+面试60%合成总成绩",
  "condition": "招聘对象：（一）应届毕业生：2025年9月1日至2026年8月31日毕业的国内普通高等院校毕业生（非在职）及国（境）外高校毕业生（非在职）。（二）社会人员：除毕业生外其他符合条件的人员（须于报名首日以前取得相应毕业证和学位证书）。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；具有正常履行职责的身体条件、心理素质和符合职位要求的工作能力。学历（学位）：具有本科以上学历、学士以上学位；国（境）外高校毕业生须于报名首日前取得中国教育部留学服务中心认证的《国（境）外学历学位认证书》；以应届毕业生身份报考的，如报名时未提交与报考岗位相对应的学历及学位证书的，可允许延迟至2026年8月31日前提交，如到期未提交的将不予聘用；以社会人员身份报考的须于报名前取得与报考岗位相对应的学历学位证书。专业：报考人员所学专业与招聘岗位专业要求相符（本科专业或研究生专业任一符合即可报考），所学专业以毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；专业未列入《广东省2026年考试录用公务员专业参考目录》但主要课程与招聘岗位要求专业的课程基本一致的，报名时须提交所学专业课程成绩单（毕业院校盖章）、院校出具的课程对比情况和认定为相近专业的说明，审核通过视为专业对口；三水区公办学校临聘教师（特指在三水区公办学校任教累计三学年以上的现任临聘教师）报考义务教育阶段招聘岗位的，可报考与所学专业相符的岗位，亦可报考与教师资格证任教学科相符的岗位；以学科教学、课程与教学论、小学教育等专业报考且所学专业无培养方向的，需提交院校出具的培养方向证明。教师资格：报考义务教育阶段岗位的须具备初中以上学段相应学科教师资格证；报考高中学段岗位的须具备高中以上学段相应学科教师资格证；报考科学教师岗位的须具备初中以上学段的科学、物理、化学、生物任一学科教师资格证；2026年毕业生在报名时如无法提交教师资格证的，须提交承诺书，承诺于2026年8月31日前取得教师资格证，否则取消聘用资格。具体条件——应届毕业生须同时符合：（1）年龄要求38周岁以下；（2）报考专业成绩要求综合排名在本专业学生前30%或学科平均分在80分以上或平均学分绩点在3.0以上。社会人员须符合下列条件之一：（1）获得过县区级以上人民政府（或教育行政部门）授予的个人综合性荣誉称号，或参加教育主管部门及其直属业务部门组织的教育教学能力比赛获县区级二等奖以上，年龄要求在38周岁以下；（2）具有研究生学历、硕士以上学位的，年龄要求在38周岁以下，博士研究生年龄放宽至43周岁以下；（3）具有中级以上教师系列职称（具有中级职称的年龄要求40周岁以下、具有副高以上职称的年龄放宽至45周岁以下）；（4）在三水区公办学校任教累计三学年以上（即具有6个以上完整学期或36个月以上任教时间）的现任临聘教师，年龄要求在38周岁以下。不得报考情形：三水区公办学校在编教师；前期已参加佛山市三水区2025-2026学年度其他场次编制教师招聘考试且已进入体检环节的；在我区以往教师招聘考试、体检或考察中认定有违纪行为的；受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的。",
