  "exam": "综合能力测评（侧重考察考生职业素养和从教潜能，满分100分、合格线60分，按1:3比例确定考试人选，成绩不计入考试总成绩）+笔试（闭卷，内容为教学设计方面内容，满分100分、合格分60分，按40%折算计入考试总成绩）+面试（说课，满分100分、合格分70分，按60%折算计入考试总成绩）；笔试、面试成绩按4:6比例合成总成绩",
  "condition": "招聘对象：国内普通高等院校2026年应届毕业生（非在职），以及教育部承认学历学位且于2025年9月至2026年8月期间毕业的国（境）外院校毕业生（非在职）。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；具有适应岗位要求的身体条件；具有岗位所需的其他条件。具体条件：①报考年龄为33周岁以下，博士研究生年龄可放宽至38周岁以下（年龄计算截至报名首日）；②具有本科以上学历、学士以上学位，须于2026年8月31日前取得相应毕业证书、学位证书，国（境）外毕业生还须取得中国教育部留学服务中心认证的《国（境）外学历学位认证书》，毕业时间以毕业证书落款日期为准；③专业对口（本科专业或研究生专业任一符合即可报考），报考人员须按《广东省2026年考试录用公务员专业参考目录》进行报考，所学专业应符合报考岗位的专业要求，所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；对于学科教学、课程与教学论、小学教育等专业，如就业推荐表或成绩单上的专业名称无培养方向，需提供院校出具的培养方向证明；所学专业未列入《广东省2026年考试录用公务员专业参考目录》（即没有专业代码）的，可选择专业目录中的相近专业报考，所学专业必修课程须与报考岗位要求专业的主要课程基本一致，并提供毕业证书、所学专业课程成绩单（须教务部门盖章）、原毕业院校出具的认定为相近专业的证明等材料；④报考专业成绩平均分在75分以上，或者平均学分绩点在2.5以上；⑤具有与报考岗位相对应的教师资格证（持有高学段教师资格证的可应聘低学段教师岗位，报考义务教育阶段岗位的须具备初中以上学段教师资格证，报考科学岗位的须具备科学或数学学科教师资格证）；考生如暂无教师资格证，须提交承诺书，承诺于2027年8月31日前提交教师资格证，否则取消聘用资格。薪酬待遇：获聘人员为事业单位编制工作人员，聘为专业技术岗位12级以上。不得报考情形：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；已参加佛山市三水区2025-2026学年其他场次编制教师招聘考试且进入体检环节的。",
