  "stage": "小学/初中",
  "title": "佛山市禅城区教育系统2026年面向社会公开招聘中小学教师公告（第二场）",
  "posts": "佛山市禅城区公办中小学、特殊教育教师（事业单位编制），含澜石中学等招聘单位",
  "count": "100",
  "staffing": "事业编",
  "enroll": "2026年7月7日9:00至2026年7月13日17:00（5个工作日，逾期不接受报名；登录佛山市禅城区教育局门户网站 http://www.chancheng.gov.cn/ccjy 报名系统）",
  "exam": "笔试（2026年7月下旬，主要测评基本能力，总分100分、合格分60分，按40%计入总成绩；按岗位招聘计划从高分到低分按比例确定进入面试，招聘计划数为1人的岗位按1:4、2人及以上的岗位按1:3）—资格复审—面试（2026年8月，重点考查综合素养，总分100分、合格分70分，按60%计入总成绩）；具有博士学位的报考人员免笔试，不占用同岗位面试推荐名额，通过资格初审即可直接进入面试环节，其面试成绩为考试总成绩；总成绩从高分到低分排序，按招聘岗位等额确定进入体检环节人选（最低拟录用分数控制线为70分）",
  "condition": "招聘对象：（一）应届毕业生：2025年9月1日起至2026年8月31日期间毕业，国家统一招生的普通高等院校毕业生（非在职）或国（境）外院校的毕业生（非在职），毕业时间以毕业证书落款日期为准。（二）社会人员：除应届毕业生以外其他符合条件的人员（须于报名开始前取得相应毕业证书和学位证书）。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件和心理条件；具有岗位所需的专业技能及其他条件。报考人员须符合以下基本条件：（1）应届毕业生须符合下列条件之一：①国家承认的博士学位（在读或已经取得）；②最高学历在读期间，综合考评成绩（或学业成绩）排名在本专业前30%，或各学科平均分在82分以上，或平均学分绩点达到3.2以上。（2）社会人员须符合下列条件之一：①具有国家承认的研究生学历并取得相应硕士、博士学位；②具有教师系列中级以上职称；③在禅城区属地范围内的学校（不含幼儿园）连续任教满一学年的在岗非编教师（即2025年9月1日起至今在我区学校任教，需学校提供证明）。年龄：38周岁以下（即1987年7月7日以后出生），年龄计算截止时间为报名开始当天；符合下列条件之一年龄可放宽至45周岁（即1980年7月7日以后出生）：①具有教师系列高级及以上专业技术职称；②具有博士学位；③禅城区属地范围内的学校（不含幼儿园）在岗非编教师。学历学位：具有国家承认的学历及学位（要求详见附件1）；应届毕业生须于2026年8月31日前取得毕业证书和学位证书，否则取消聘用资格。专业：所学专业符合以下条件之一——（1）专业相符，具体参考《广东省2026年考试录用公务员专业参考目录》；（2）专业相近，所学本科或研究生专业（含海外学历学位）与招聘岗位要求专业相近但又未列入目录范围，所学专业主要课程与招聘岗位要求专业的主要课程超过一半基本一致的，可直接填写毕业证书上专业名称和提交成绩表进行报考，对比审核后认定为相近专业的不影响报名应聘；（3）国家优秀中小学教师培养计划（“国优计划”）毕业生按照取得的中小学教师资格证任教学科报名应聘相应学科教师岗位，所学专业与岗位要求专业不一致、本科与研究生专业不一致的不影响报名应聘；所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据。教师资格证：报考人员须持有与招聘岗位相应学段（含以上）及学科的教师资格证书，其中（1）报考小学教师岗位，须具备初中及以上学段对应学科的教师资格证书；（2）报考初中教师岗位，须具备高中及以上学段对应学科的教师资格证书；（3）应届毕业生须于2026年8月31日前取得符合报考岗位条件的教师资格证书，未按时取得者将取消聘用资格。语文教师岗位须取得二级甲等或以上普通话测试合格证书（应届毕业生暂未取得的须于2026年8月31日前取得）；英语教师岗位须提供国家专业英语八级合格证书，或雅思7分（含）以上、托福95分（含）以上成绩单（应届毕业生暂未取得的须于2026年8月31日前取得）。不得报名情形：受过刑事处罚；被开除中国共产党党籍；被开除公职；被依法列为失信联合惩戒对象；按《事业单位人事管理回避规定》聘用后构成回避关系；佛山市禅城区公办学校在编教师；前期已参加佛山市禅城区2025-2026学年度其他场次公开教师招聘考试且已进入体检环节的。薪酬待遇：获聘人员为事业单位编制人员，由区财政统发。",
