  "early": false,
  "stage": "高中",
  "title": "佛山市第一中学2026年公开招聘教师（第二轮）公告",
  "posts": "佛山市第一中学（市教育局直属全寄宿高级中学）从事普通高中教育教学工作的专任教师：英语教师2人、物理教师2人、数学教师1人、信息学竞赛教练2人",
  "count": "英语2、物理2、数学1、信息学竞赛教练2",
  "staffing": "事业编",
  "enroll": "2026年5月20日9:00至2026年5月26日17:00（网上报名，投递至邮箱 fsyz82838610@163.com ，邮件标题使用“应聘岗位+姓名+学校+专业+学历+电话号码”格式）",
  "exam": "笔试（2026年5月30日，采取学科专业知识、教育教学技能测试形式，总分100分、合格分60分，按40%计入综合成绩，从高分到低分按1:4确定试教人员）+试教（2026年5月31日，含试教和问答，满分100分、合格线70分）+面试（2026年5月31日，采用无领导小组或结构化考核方式，总分100分、合格线70分）；笔试、试教、面试成绩按4:3:3比例合成综合成绩，综合成绩总分100分、合格分数线70分",
  "condition": "招聘对象分为应届毕业生和社会人员两类。（一）应届毕业生：具有研究生学历及硕士学位（含）以上的普通高等院校2026届毕业生及国（境）外毕业生（即于2025年9月1日至2026年8月31日期间取得毕业证书及学位证书的人员，以证书落款日期为准）。（二）社会人员：本科学历及学士学位（含）以上且具有2年以上相应学科教育教学工作经历的高中在职教师（含临聘）。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件和心理条件；具备岗位所需的专业技能及其他条件。年龄要求：38周岁及以下，或者符合以下条件之一的人员年龄可放宽至45周岁：①具有博士研究生学历学位；②具有相应学科高中高级教师职称；③指导学生获得全国中学生奥林匹克竞赛（物理、数学或信息学）省一等奖及以上；年龄计算截止时间为报名开始当天。专业要求：专业名称参照《广东省2026年考试录用公务员专业参考目录》；如应聘人员所学专业未列入目录的，可选择专业要求中相近专业应聘，但所学专业必修课程须与应聘岗位要求的专业主要课程超过一半基本一致，并提供原毕业院校出具的认定为相近专业的证明方可应聘。2026届毕业生和国（境）外毕业生须于2026年8月31日前取得与招聘岗位条件相应的毕业证书和学位证书；留学回国（境）的毕业生还须取得与招聘岗位条件相应的由中国教育部留学服务中心出具的国（境）外学历学位认证证书。教师资格证要求：报考时须持与招聘岗位相应学科的高中或以上教师资格证书；暂未取得教师资格证的应届毕业生，须提交个人承诺书，承诺于2026年8月31日前取得相对应学科的高中或以上教师资格证书，到期未取得的取消岗位聘用资格。不得报名情形：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；法律、法规规定的其他情形。",
