  "exam": "公告未明确（招聘考点设在佛山市高明区，具体地点待通知）",
  "condition": "招聘对象：1.2026届毕业生（非在职）：①国内普通高等院校2026届毕业生（非在职）；②2025年5月9日至2026年5月9日期间取得国（境）外学历学位的毕业生（非在职），并须在入编前完成教育部门认证的留学回国人员；毕业时间以毕业证书落款日期为准。2.社会人员：2026届毕业生（非在职）外，其他毕业于国内普通高等院校或取得国（境）外学历学位，并且符合条件的人员。基本条件：具有中华人民共和国国籍；拥护中华人民共和国宪法，拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；具有正常履行职责的身体条件和心理素质；具有符合职位要求的工作能力；具有普通高等院校本科以上学历，学士以上学位；国（境）外学历报考者须在办理入编手续前提供教育部留学服务中心出具的国（境）外学历学位认证。专业要求符合以下条件之一：（1）专业相符——所学专业与招聘职位专业要求相符，具体参考《广东省2026年考试录用公务员专业参考目录》，报考者在报名系统中填写专业须按所学专业如实填写，辅修专业不作为报考依据；（2）专业相近——所学专业[含国（境）外学历学位]与招聘职位要求专业相近但又未列入目录范围，所学专业主要课程与招聘职位要求专业的主要课程基本一致的，可选择专业目录中的相近专业报考，在报名时提供毕业证书[国（境）外已毕业的提供]、所学专业课程成绩单（毕业院校盖章）、院校出具的课程对比情况说明和认定为相近专业的说明；报考者所学专业已经列入《广东省2026年考试录用公务员专业参考目录》的，不能再作相近专业报考；港澳学习、国外留学生还须提供相应材料的中文翻译件（由有资质机构出具）。注：①课程与教学论、学科教学硕士、翻译等专业，如成绩单上的专业名称无培养方向，考生须提供院校出具的培养方向证明；②要求本科及以上学历的岗位，若以研究生学历报考，则本科或研究生任一阶段的专业符合岗位要求即可。教师资格证、年龄、荣誉等具体门槛公告正文未在本段列出（公告附件1职位表载明）。",
