  "title": "2025年下半年广州市教育系统校园招聘“优才计划”公告",
  "posts": "广东广雅中学、广州市执信中学、广州市第二中学、广州市第六中学、广州市铁一中学、广东华侨中学、广州外国语学校等市教育局直属及各区中小学，语文、数学、英语、物理、化学、生物、政治、历史、地理、体育、音乐、美术、信息技术、心理等学科教师",
  "count": "385（北京考点、武汉考点合计）",
  "staffing": "事业编",
  "enroll": "北京考点2025年10月11日9:00-10月16日17:00；武汉考点2025年10月24日9:00-10月30日17:00",
  "exam": "面试（基本能力测试+说课/试教）+笔试。北京考点：基本能力测试预计10月17日下午、说课/试教预计10月17-18日、笔试预计10月19日；武汉考点：基本能力测试预计10月31日下午、说课/试教预计10月31日-11月1日、笔试预计11月2日。笔试内容为行政职业能力测验、教育学、心理学等。综合成绩=面试（说课/试教）60%+笔试40%，合格成绩60分。A类岗位基本能力测试为实操技能测试，B类岗位为小组讨论（报名人数与岗位招聘数≤5:1的岗位免考基本能力测试）",
  "condition": "招聘对象为2026年毕业生，即2026年1月1日至12月31日期间取得学历、学位证书的毕业生（含持国（境）外学历学位证书人员）。年龄：本科生35周岁以下，硕士研究生40周岁以下，博士研究生45周岁以下（截至报名首日）。专业及代码参照《广东省2025年考试录用公务员专业参考目录》设置，所学专业按所获毕业证书上的专业为准，毕业证书专业名称后以括号形式列出的培养方向不能作为报考专业依据，辅修专业、学位种类均不作为所学专业依据；所学专业未列入目录的，须在报名时提供课程成绩单（毕业院校盖章），经招聘单位认定为相近专业方可报考。可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求，且须在2026年12月31日前取得最高学历毕业证书、学位证书，否则不予聘用。非广州市常住户籍人员应符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市户口迁入条件；为便于管理，非广州市户籍考生须在录用后将户籍迁至广州市。考生须承诺在转正前取得相应教师资格证书，否则用人单位将终止聘用。各岗位具体学历、学位、专业及学科方向要求详见附件岗位需求表。公告正文未设院校门槛、荣誉或成绩排名要求。",
