  "condition": "招聘对象为2026年毕业生，即于2026年1月1日至2026年8月31日期间取得硕士研究生及以上学历、硕士及以上学位证书的毕业生（含持境外学历学位证书人员），且须同时具有本科学历、学位；毕业时间以毕业证书和学位证书落款时间为准。广东省生源的2026年毕业的教育部直属师范大学公费师范生报考可放宽到本科学历和学士学位。资格条件：应聘人员年龄在38周岁以下（按报名首日为2026年1月1日计算，即1987年1月2日及以后出生）。以硕士研究生学历报考者，本科、研究生阶段专业均须符合专业要求；以博士研究生学历报考者，符合以下4种情况之一视为专业符合要求：①本科及硕士研究生专业与职位要求专业一致；②本科及博士研究生专业与职位要求专业一致；③硕士及博士研究生专业与职位要求专业一致；④本科、硕士、博士专业与职位要求专业均一致。非广州市常住户籍人员应符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市户口迁入条件；为便于管理，非广州市户籍考生须在聘用后将户籍迁至广州市。拟聘用人员须承诺5年最低服务期，聘用后按“区管校聘”政策管理，须服从区教育局和聘用学校工作调配并参加区内交流轮岗。专业目录参照《广东省2026年考试录用公务员专业参考目录》。公告未设院校门槛、荣誉或成绩排名要求。",
