  "exam": "面试（基本能力测试小组讨论+说课/试教）+笔试，均预计2026年6月中旬在长沙市举行；综合成绩=面试（说课/试教）60%+笔试40%，合格60分。基本能力测试按1:5确定进入说课/试教人员，说课/试教按1:3确定进入笔试人员",
  "condition": "招聘对象为2026年毕业生，即于2026年1月1日至2026年12月31日期间取得学历、学位证书的毕业生（含持国〔境〕外学历学位证书人员）。年龄：本科生38周岁以下；硕士研究生40周岁以下；博士研究生45周岁以下（截至报名首日）。具有本科（含）以上学历及学士（含）以上学位；如以研究生学历及硕士（含）以上学位报考的，必须同时具备本科学历学士学位。各招聘岗位的专业及代码参照《广东省2026年考试录用公务员专业参考目录》设置，所学专业按所获毕业证书上的专业为准，括号内培养方向不能作为报考专业依据，辅修专业、学位种类均不作为所学专业依据；未列入目录的须在报名时提供课程成绩单（毕业院校盖章），经招聘单位认定为相近专业方可报考；以相近专业报考和持国（境）外学历考生无法提供专业方向证明材料的，是否符合要求由招聘单位会同区教育局认定。可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求，且须在2026年12月31日前取得最高学历毕业证书、学位证书，否则不予聘用。教师资格：须具有满足招聘岗位学段和学科相应要求的教师资格证，报考中学岗位须具有相应学科教师资格证，报考小学教师岗位对所持教师资格证的学科不作要求，高学段教师资格证书可以报考低学段教师岗位；暂未取得的须承诺在办理入职手续前取得，否则取消聘用资格。普通话：报考语文教师岗位须二级甲等或以上，其他岗位二级乙等或以上（暂未取得须承诺入职前取得）。英语岗位须提供国家专业英语八级合格证书或雅思7分、托福95分（含）以上成绩单（暂未取得须承诺入职前取得）。非广州市常住户籍人员应符合穗府办规〔2025〕9号规定的广州市户口迁入条件；非广州市户籍考生须在聘用后将户籍迁至广州市。前期参加各类公开招聘并已与越秀区教育局局属单位签约人员不得报考。公告未设院校门槛、荣誉或成绩排名要求。",
