  "enroll": "北京考点、武汉考点均为2025年10月24日9:00至11月1日17:00；现场宣讲2025年10月31日15:00-17:00；现场资格审查2025年11月1日8:30-11:30、14:00-17:00；准考证打印预计2025年11月2日17:00起",
  "exam": "面试（采用试教方式，预计2025年11月3-4日）+笔试（教育学、心理学等相关知识，预计2025年11月5日）；面试成绩占60%、笔试成绩占40%，合格成绩60分；招聘对象为博士研究生的岗位免笔试。根据面试成绩按招聘岗位数1:3确定进入笔试人员",
  "condition": "招聘对象为2026年毕业生，即于2026年1月1日至2026年12月31日期间取得学历、学位证书的毕业生（含持国（境）外学历学位证书人员）。具有本科及以上学历、学士及以上学位，其中以研究生学历、硕士及以上学位报考的考生须同时具有本科学历、学士学位；2026年广东省生源教育部直属师范大学公费师范毕业生报考部分岗位，可放宽到本科学历和学士学位（详见岗位需求表“其他要求”栏）。年龄：本科生38周岁以下（1986年10月24日（含）后出生）；硕士研究生40周岁以下（1984年10月24日（含）后出生）；博士研究生45周岁以下（1979年10月24日（含）后出生）。取得与应聘岗位相应的教师资格证，暂未取得的须承诺在入职后试用期内取得相应资格证书，否则不予转正并终止聘用。应聘语文教师岗位普通话水平测试必须达到二级甲等或以上（暂未取得的须承诺在毕业前取得）。应聘英语教师岗位要求具有国家英语专业八级合格证书（须承诺毕业前取得）或雅思7分或托福95分（含）以上成绩单；应聘其他岗位不作要求。所学专业须符合应聘岗位相关专业（代码）要求，专业名称及代码参照《广东省2026年考试录用公务员专业参考目录》，所学专业以所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；未列入目录或无专业代码的可选相近专业报考，但所学专业必修课程须与报考岗位要求专业的主要课程基本一致，并在资格审查时提供毕业院校盖章的课程成绩单、院校出具的课程对比情况说明及毕业院校设置专业的依据等材料，经招聘单位及主管部门认定为相近专业；对含有两个以上培养方向的专业，招考岗位已明确具体培养方向的须符合该方向方可报考，毕业证书或就业推荐表未列明方向的须提供毕业院校出具的专业方向培养证明。报考人员可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求。非广州市户籍人员还须符合穗府办规〔2025〕9号规定的广州市人才引进条件。每个考生只能选择1个考点且限报其中1个岗位。不得报考情形含：广州市天河区教育系统事业单位在职在编人员、已通过2025年广州市天河区教育系统校园招聘“优才计划”考试并进入体检环节的2026年毕业生。公告未设院校门槛、荣誉或成绩排名要求。",
