  "condition": "招聘对象为2026年毕业生，即于2026年1月1日（含）至2026年12月31日（含）期间取得学历、学位证书的毕业生（含持国（境）外学历学位证书人员）。学历要求硕士研究生及以上（详见岗位需求表）。基本条件包含：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；非广州市常住户籍人员应符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市户口迁入条件。应聘人员可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求，且上述人员须在2026年12月31日（含）前取得最高学历的毕业证书、学位证书，逾期未取得的取消其聘用资格。每人仅限报考一个岗位，逾期不接受报名。公告正文未明确院校门槛、荣誉/成绩排名要求及教师资格证具体取得时点，详见岗位需求表。",
