  "title": "广州市教育局直属事业单位2026年第一次公开招聘教师公告",
  "posts": "广州外国语学校、广州市铁一中学、广东广雅中学、广东华侨中学、广州市旅游商务职业学校、广州市启聪学校等，覆盖小学到高中阶段，含语文、数学、体育、心理健康教育、无人机操控与维护等教师岗位",
  "count": "205",
  "staffing": "事业编",
  "enroll": "2026年3月11日9:00至3月17日17:00（全国事业单位招聘网 http://www.qgsydw.com）；考试网上确认2026年3月20日12:00-3月22日12:00；准考证打印2026年3月25日15:00后",
  "exam": "笔试暂定2026年3月28日（内容为学科相关知识或专业综合素养、教育学、心理学等，满分100分、合格60分，按40%折算）；现场资格审查；面试（说课、试教、实操、问答、专业技能测试等，满分100分、合格60分，按60%折算）；综合成绩=笔试40%+面试60%，合格60分；免笔试岗位面试成绩即为综合成绩。各岗位笔试开考比例原则上不低于1:3（部分紧缺专业岗位经批准可调整为1:2）",
  "condition": "招聘对象分三类：（一）2026年毕业生：指于2026年1月1日至2026年12月31日期间取得毕业证书的毕业生（含持国（境）外学历学位证书人员）；（二）非2026年毕业的往届生：指于2025年12月31日前取得毕业证书的非在读人员（含持国（境）外学历学位证书人员）；（三）“不限”：以上两类人员均可。资格条件中对工作年限有要求的，必须提供劳动合同、社保缴费记录（不含在校生实习、创业经历）。年龄要求：具有本科学历的38周岁以下；具有研究生学历或与报考岗位相对应的中级专业技术资格的40周岁以下；具有博士学位或与报考岗位相对应的副高级专业技术资格的45周岁以下；具有与报考岗位相对应的正高级专业技术资格的50周岁以下；岗位需求表中有明确年龄、学历学位要求的以岗位需求表为准。教师资格：所有应聘人员（2026年毕业生和广州幼儿师范高等专科学校的应聘人员除外）必须持有与报考岗位相对应的教师资格证书；2026年毕业生须承诺在转正前取得相应教师资格证书，否则用人单位将终止聘用；报考广州幼儿师范高等专科学校教师岗位的须承诺正式聘用后2年内取得高校教师资格证书。应聘语文教师职位，普通话水平测试必须达到二级甲等或以上。专业要求严格：所有应聘人员所学的专业必须与报考的岗位相对应，招聘专业名称及代码按照《广东省2026年考试录用公务员专业参考目录》设置，所学专业按所获毕业证书上的专业为准，毕业证书上专业名称后以括号形式列出的培养方向不能作为报考专业的依据，辅修专业、学位种类均不作为所学专业依据；如所学专业未列入专业参考目录，但主要课程与报考岗位所要求专业的主要课程基本一致的，须在现场资格审查时提供加盖公章的课程成绩单、院校出具的课程对比情况说明等，经认定为相近专业方可视为符合。可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求。非广州市常住户籍人员应符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市户口迁入条件；为便于管理，非广州市户籍考生原则上须在聘用后将户籍迁至广州市。2026年毕业生如未在2026年12月31日前获得岗位要求的学历和学位证书，将被取消聘用资格。广州市教育局直属事业单位在职在编人员不受理报考。各岗位具体专业、学历、学位及其他要求详见附件1岗位需求表。",
