  "exam": "笔试采取闭卷考试方式，考试时间120分钟，满分100分、合格成绩60分，内容主要为：教育界关注的热点问题（含教育教学理论、方式、方法和价值观等知识和应用）、教育学与心理学的知识和应用、教师职业道德等教育通识、教育政策法规；笔试成绩按四舍五入保留小数点后2位；资格复审、面试及综合成绩计算方式详见公告",
  "condition": "招聘对象为：（一）2026年毕业生，指于2026年1月1日（含）至2026年12月31日（含）期间取得毕业证书及学位证书的毕业生（含持国（境）外学历学位证书人员）；（二）非2026年毕业的往届生，指2025年12月31日（含）前取得毕业证书及学位证书的非在读人员（含持国（境）外学历学位证书人员）；（三）广东省生源的2026届（含往届未就业毕业生）教育部直属师范大学公费师范生。应聘人员须同时符合公告所列条件和《岗位表》规定条件。基本条件包括：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；非广州市常住户籍人员应符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办〔2025〕9号）规定的广州市户口迁入条件；招聘公告要求的其他条件；法律、法规规定的其他条件。年龄要求：具有本科学历的38周岁以下；具有研究生学历或中级专业技术资格的40周岁以下；具有博士学历或副高级专业技术资格的45周岁以下；具有正高级专业技术资格的50周岁以下。应聘人员可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求。各岗位专业、学历、学位及其他要求详见《岗位表》，专业名称及代码参照《广东省2026年考试录用公务员专业参考目录》设置。每人仅限报考一个岗位，逾期不接受报名。公告正文未设院校门槛、荣誉或成绩排名要求（详见岗位表）。",
