  "title": "广州市黄埔区教育局2026年春季公开招聘在编教职员公告",
  "posts": "黄埔区教育系统在编教职员（中小学各学科教师等），共116个职位、179人，如广州市黄埔区开元学校中学化学教师、黄埔区教育局统招中小学语文教师等",
