  "enroll": "2026年4月11日9:00至4月17日17:00（全国事业单位招聘网 http://www.qgsydw.com）；准考证打印2026年4月22日15:00后",
  "exam": "笔试2026年4月25日，内容为学科专业知识、教育学、心理学、教育政策法规、时事政治、教材教法、公共基础知识、行政职业能力测验等；招聘对象为博士研究生的岗位免笔试；其余按现场资格审查、面试、体检、考察、公示、聘用等程序进行。各岗位笔试开考比例原则上不低于1:3",
  "condition": "招聘对象为：（一）2026年毕业生：指于2026年1月1日至2026年12月31日期间取得毕业证书及学位证书的人员〔含持国（境）外学历学位证书人员〕；（二）非2026年毕业的往届生：指于2025年12月31日（含）前取得毕业证书及学位证书的非在读人员〔含持国（境）外学历学位证书人员〕。基本条件：具有中华人民共和国国籍；遵守宪法和法律，拥护中国共产党领导和社会主义制度；遵纪守法，具有良好的政治素质和道德品行；热爱教育事业，具有正常履行职责的身体条件、心理素质和符合岗位要求的工作能力。学历学位：具有本科（含）以上学历及学士（含）以上学位，招聘岗位需求表中有明确学历、学位要求的以岗位需求表为准；2026年毕业生如未在2026年12月31日前获得岗位招聘条件所要求的学历和学位证书，将被取消聘用资格。户籍：非广州市户籍人员还须符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市人才引进条件。专业：所学专业须与报考岗位相对应，参照《广东省2026年考试录用公务员专业参考目录》。教师资格：取得与应聘岗位相应的教师资格证，2026年毕业生暂未取得的须承诺在入职后试用期内取得，否则不予转正并终止聘用。部分往届生岗位另设职称、工作经历与荣誉门槛，例如“中小学语文教师D”岗要求具有与岗位相对应的初级及以上职称，并同时满足以下条件之一：①参加教育行政部门及其直属业务部门组织的教学技能比赛或班主任技能竞赛、课堂教学比赛、优质课比赛、精品课大赛、学科命/解题大赛等相关类型竞赛获得县（区）级二等奖及以上或地市级三等奖及以上，或获得市级及以上“一师一优课”“基础教育精品课”，或获得县（区）级及以上名教师（班主任）、骨干教师（班主任）、优秀教师（班主任）、模范教师（班主任）、学科带头人、名教师（名班主任）工作室主持人、教坛新秀、教学能手、优秀教育工作者等教育类荣誉称号；②至少三年中小学正（副）班主任经历；③具有与岗位相对应的中小学一级教师及以上职称。“中学化学教师”岗要求具有一年及以上对应学科普通中学任教经历且报名时正在普通中学任教，同时具有初三或高三毕业班任教经历。有具体工作经历要求的岗位须提供工作单位出具的工作经历证明及相应年限的社保记录和劳动合同，在校期间的社会实践经历不视为工作经历。不得报考人员含：广州市黄埔区教育系统事业单位在职在编人员、已通过2025年广州市黄埔区教育系统校园招聘考试并进入体检环节的2026年毕业生。",
