  "title": "2026年广州市海珠区公开招聘编制教师公告",
  "posts": "海珠区中小学、职业学校及幼儿园（如广州市第五中学、广州市第四十一中学、广州市绿翠现代实验学校、广州市海珠工艺美术职业学校、启能学校等），语文、数学、英语、物理、化学、生物、政治、历史、地理、体育、美术、信息科技、心理健康等学科教师",
  "count": "265（公告岗位表共257个职位）",
  "staffing": "事业编",
  "enroll": "2026年4月7日9:00至4月13日17:00（全国事业单位招聘网 http://www.qgsydw.com）；考试网上确认2026年4月14日9:00-4月15日17:00；准考证打印2026年4月17日9:00后",
  "exam": "笔试暂定2026年4月19日（闭卷120分钟）：中小学校、职业学校教师岗位及启能学校非幼儿教师岗位笔试内容包括学科专业知识，教育学、心理学、教育政策法规、教育教学管理和师德师风等相关知识；幼儿园教师岗位及启能学校幼儿教师岗位笔试内容包括学前教育学、学前心理学、教育政策法规、幼儿与班级管理和师德师风等。笔试满分100分、合格线60分，按40%折算计入综合成绩；按笔试成绩由高到低以1:5比例确定进入资格复审人员；其后为资格复审、面试、体检、组织考察、公示、办理聘用等程序。笔试开考比例原则上不低于1:3",
  "condition": "招聘对象为：（一）非2026年毕业的往届生：指于2025年12月31日前取得学历学位证书的非在读人员，含持国（境）外学历学位证书人员；（二）2026年毕业生：指于2026年1月1日至2026年12月31日期间取得学历学位证书的毕业生，含持国（境）外学历学位证书人员；（三）“不限”：以上两类人员均可。基本条件：具有中华人民共和国国籍；遵守中华人民共和国宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；具有正常履行岗位职责的身体条件和符合岗位要求的工作能力；要求本科及以上学历和学士及以上学位，并具有岗位所需的任职资格、专业技术条件及技能要求。专业：非2026年毕业的往届生本科及以上学历所学专业必须符合报考岗位的专业要求，或必须具有与报考岗位学科相对应的专业技术资格证；2026年毕业生本科及以上学历所学专业必须符合报考岗位的专业要求（岗位表按本科专业与研究生专业分别列明，如中学语文教师岗本科阶段须为汉语言文学、汉语言、汉语国际教育、应用语言学等）。教师资格：非2026年毕业的往届生必须具备相对应的教师资格证（报考幼儿园教师须具幼儿园教师资格证，报考小学教师须具小学及以上教师资格证，报考中学教师须具中学及以上教师资格证）；2026年毕业生聘用人员须在转正前取得相对应的教师资格证，否则用人单位将不予转正并解除聘用。年龄：非2026年毕业的往届生中，本科学历和学士学位38周岁以下（1987年4月7日及以后出生），硕士研究生学历或硕士学位或教师系列中级专业技术资格40周岁以下（1985年4月7日及以后出生），博士研究生学历或博士学位或教师系列副高级及以上专业技术资格45周岁以下（1980年4月7日及以后出生）；2026年毕业生报考年龄在38周岁以下。普通话：报考语文教师岗位须二级甲等及以上；其他学科二级乙等及以上。英语岗位：须提供国家专业英语八级合格证书或雅思7分或托福95分及以上成绩单（2026年毕业生须承诺在毕业前取得相应证书，否则取消聘用资格）。2026年毕业生须在2026年12月31日前获得岗位要求的学历和学位证书，否则取消聘用资格。非广州市常住户籍人员应符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市户口迁入条件。不得报考情形含：广州市海珠区教育系统事业单位在职在编人员、2025年下半年广州市海珠区教育系统高校“优才计划”体检环节合格的报考人员等。",
