  "enroll": "2026年7月27日至7月31日（网络报名，全国事业单位招聘网 https://www.qgsydw.com）；考试网上确认2026年8月1日-8月2日",
  "exam": "笔试（含学科专业知识、教育学、心理学等，占40%）→资格复审→面试（专业技能测试/试教，占60%）；面试时间为2026年9月6日（分上、下午签到，各岗位具体签到时间、地点详见准考证）；面试满分100分、合格成绩60分，低于60分不能进入下一环节；试教环节教具由考场提供，考生不允许自带口哨及各类教具（音乐、体育教师岗位考生可带个人技能展示器具，仅能在个人技能展示环节使用）",
  "condition": "招聘对象为：（一）2026年毕业生：指于2026年1月1日（含）至2026年12月31日（含）期间取得毕业证书的毕业生〔含持国（境）外学位证书人员〕；（二）非2026年毕业的往届生：指于2025年12月31日（含）前取得毕业证书的非在读人员〔含持国（境）外学位证书人员〕；（三）“不限”：以上两类人员均可；（四）国家优秀中小学教师培养计划（“国优计划”）毕业生可按照取得的中小学教师资格证任教学科报名应聘相应学科教师岗位，所学专业与岗位要求专业不一致、本科与研究生专业不一致的不影响报名应聘；（五）2026届广东省生源的教育部直属师范大学公费师范生；（六）港澳居民符合粤人社规〔2021〕34号规定和本公告规定的可报考相关岗位。资格条件：1.各岗位具体要求见《岗位表》；2.年龄条件：本科生报考年龄38周岁（含）以下；硕士研究生或具有与报考岗位相对应的中级专业技术资格（职称）的考生40周岁（含）以下；博士研究生或具有与报考岗位相对应的副高级及以上专业技术资格（职称）的考生45周岁（含）以下；年龄计算截至报名首日；3.报考语文教师岗位的普通话水平测试必须达到二级甲等或以上；4.须持有对应教师资格证。专业名称及代码参照《广东省2026年考试录用公务员专业参考目录》设置。部分岗位另设荣誉与经历门槛（例：广州市荔湾区西关广雅实验学校“初中英语教师A”岗要求课程与教学论、学科教学硕士、教育学专业均须是英语相关方向，且须具备以下条件之一：①参加教育行政部门及其直属业务指导部门或政府下属教育业务主管部门组织的教学技能比赛或班主任技能竞赛【含课堂教学比赛、学科命/解题大赛、班主任技能大赛等相关类型竞赛】获得县（区）级【不设县、区的地级市须为镇、街道级】二等奖及以上或地市级三等奖及以上，或优质课、精品课获评地市级及以上奖励；②获得县（区）级【同上】及以上人民政府或教育行政部门授予的名教师（班主任）、骨干教师（班主任）、优秀教师（班主任）、教坛新秀、教学能手、优秀教育工作者之一称号）。",
