  "posts": "天河区教育局直属事业单位（中小学），涵盖语文、数学、英语、物理、化学、政治、历史、地理、生物、科学、信息、心理、音乐、体育、美术、特殊教育、研训员等学科岗位；含1所新开办九年一贯制学校共招聘10名教师",
