  "enroll": "2026年3月10日9:00至3月16日17:00（全国事业单位招聘网 http://www.qgsydw.com）；考试网上确认2026年3月17日9:00-3月18日17:00；准考证打印2026年3月19日17:00后",
  "exam": "笔试预计2026年3月21日或3月22日（行政职业能力测验、教育学、心理学、教育政策法规等，满分100分、合格60分，按40%折算计入综合成绩）；现场资格审查（按笔试成绩1:5确定入围，免笔试岗位按考试网上确认人数进入）；面试（教师岗位主要采用试教形式，其他岗位主要采用结构化面试、专业（技能）水平测试等形式，满分100分、合格60分，按60%折算）；综合成绩达60分及以上者方可进入体检；招聘对象为博士研究生的岗位免笔试，其面试成绩即为综合成绩。各岗位开考比例原则上不低于1:3",
  "condition": "招聘对象为：（一）“2026年毕业生”：指于2026年1月1日至2026年12月31日期间取得毕业证书及学位证书的人员〔含持国（境）外学历学位证书人员〕；（二）“非2026年毕业的往届生”：指于2025年12月31日前取得毕业证书及学位证书的非在读人员〔含持国（境）外学历学位证书人员〕；（三）“不限”：以上两类人员均可。学历学位：具有本科（含）以上学历及学士（含）以上学位，招聘岗位需求表中有明确学历、学位要求的以岗位需求表为准；2026年毕业生如未在2026年12月31日前获得岗位招聘条件所要求的学历和学位证书，将被取消聘用资格。年龄：具有本科学历的38周岁以下；具有研究生学历或与报考岗位相对应的中级专业技术资格的40周岁以下；具有博士学位或与报考岗位相对应的副高级专业技术资格的45周岁以下（相关年龄和工作经历年限等时间点计算截至报名首日）。教师资格：取得与应聘岗位相应的教师资格证，2026年毕业生暂未取得资格证书的须承诺在入职后试用期内取得相应资格证书，否则不予转正并终止聘用。普通话：应聘语文教师岗位普通话水平测试必须达到二级甲等或以上，2026年毕业生暂未取得的须承诺在毕业前取得，否则取消聘用资格。英语岗位：2026年毕业生要求具有国家英语专业八级合格证书（须承诺在毕业前取得）或雅思7分或托福95分（含）以上成绩单；非2026年毕业的往届生要求具有国家英语专业八级合格证书，或雅思7分或托福95分或大学英语六级425分（含）以上成绩单。专业要求严格：报考人员所学的专业须与报考岗位相对应，所学专业以所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；专业名称及代码参照《广东省2026年考试录用公务员专业参考目录》，未列入目录或无专业代码的可选择招聘专业中相近专业报考，但所学专业必修课程须与报考岗位要求专业的主要课程基本一致，并在资格审查时提供所学专业课程成绩单（毕业院校盖章）、院校出具的课程对比情况说明及毕业院校设置专业的依据等材料，经招聘单位及主管部门认定为相近专业；对含有两个以上培养方向的专业，招考岗位已明确具体培养方向的，报考者须符合具体培养方向方可报考，毕业证书或就业推荐表上专业未列明培养方向的，资格审查时须提供毕业院校出具的专业方向培养证明；除目录中有列出培养方向的专业外，其他毕业证上专业名称后面以括号等形式列出的培养方向不能作为报考专业的依据；报考教师岗位的非2026年毕业的往届生若已取得的中小学教师职称证中所任教学科与报考岗位学科相一致的，可视为专业一致。可用非最高学历专业报考，但用于报考的学历层次和学位层次应同时符合岗位要求。非广州市户籍人员还须符合《广州市人民政府办公厅关于重新发布广州市引进人才入户管理办法的通知》（穗府办规〔2025〕9号）规定的广州市人才引进条件。不得报考人员含：广州市天河区教育系统事业单位在职在编人员、已通过2025年广州市天河区教育系统校园招聘“优才计划”考试并进入体检环节的2026年毕业生。聘用人员实行试用期制：2026年毕业生试用期为1年；非2026年毕业的往届生入职前工作年限未满1年的试用期为1年，满1年及以上的试用期为6个月。报考人员一经报名，视同服从并接受用人单位工作安排，须服从招聘单位各类岗位、不同学段的教学安排，并接受天河区教育局工作调配、定期参加区内交流轮岗。公告未设院校门槛、荣誉或成绩排名要求。",
