  "condition": "【招聘对象】2027年毕业生（本科及以上）。【岗位与专业】一、语文教师3名：需求专业为中国语言文学(A0501)、新闻传播学(A0503)、国际中文教育(A040123)、课程与教学论(A040102)、学科教学硕士（专业硕士）(A040113)，要求硕士研究生及以上。二、数学教师3名：本科专业数学类(B0701)；研究生专业为数学(A0701)、系统科学(A0711)、统计学(A0714)、应用经济学(A0202)、课程与教学论(A040102)、学科教学硕士（专业硕士）(A040113)，要求本科及以上。三、英语教师3名：需求专业为英语语言文学(A050201)、外国语言学及应用语言学(A050211)、英语笔译硕士（专业硕士）(A050212)、英语口译硕士（专业硕士）(A050213)、课程与教学论(A040102)、学科教学硕士（专业硕士）(A040113)，要求硕士研究生及以上。四、物理教师2名：本科专业物理学类(B0702)；研究生专业为物理学(A0702)、天文学(A0704)、大气科学(A0706)、物理海洋学(A070701)、地球物理学(A0708)、力学(A0801)、机械工程(A0802)、光学工程(A0803)、材料物理与化学(A080501)、动力工程及工程热物理(A0807)、电气工程(A0808)、电子科学与技术(A0809)、信息与通信工程(A0810)、航空宇航科学与技术(A0825)、核科学与技术(A0827)、课程与教学论(A040102)、学科教学硕士（专业硕士）(A040113)，要求本科及以上。五、化学教师3名：需求专业为化学(A0703)、材料科学与工程(A0805)、冶金工程(A0806)、化学工程与技术(A0817)、环境科学与工程(A0830)、药学(A1007)、课程与教学论(A040102)、学科教学硕士（专业硕士）(A040113)，要求硕士研究生及以上。六、生物教师3名：需求专业为生物学(A0710)、生态学(A0713)、生物医学工程(A0831)、食品科学与工程(A0832)、风景园林学(A0834)、生物与医药(A0845)、生物工程(A0836)、作物学(A0901)、园艺学(A0902)、植物保护(A0904)、畜牧学(A0910)、林学(A0912)、基础医学(A1001)、课程与教学论(A040102)、学科教学硕士（专业硕士）(A040113)，要求硕士研究生及以上。原文未提及户籍、年龄、教师资格证取得时限等要求。",
