  "exam": "发布公告→网络报名→资格初审→笔试（笔试计划2026年6月13日举行）→现场资格复审→面试→体检→考察→公示→聘用；需在规定时间内确认是否参加笔试，确认后无故不参加将列入市直教师招聘限制记录",
