  "condition": "招聘对象为：（1）普通高校列入国家招生计划，具有师范类专业本科学历并取得学士学位的应往届毕业生（在国（境）外取得本科学历并取得学位的，还须于2026年8月31日前取得中国教育部留学服务中心出具的国（境）外学历学位认证证书）；（2）普通高校列入国家招生计划，具有研究生及以上学历并取得硕士及以上学位的应往届毕业生，大学期间（本科和研究生阶段）所学专业为师范类或教育类，且本科所学专业和研究生专业研究方向与应聘岗位学科一致；（3）在惠城区公办学校工作具有本科及以上学历的在职在岗合同制教学人员（须具有与报考学科相对应的教师资格证）。基本条件：具有与报考岗位相对应的教师资格证，以及与岗位要求相符的学历及专业；年龄在38周岁以下（即1988年9月1日以后出生），惠城区在职合同制教学人员除外；暂未取得教师资格证的2026届毕业生，须提供有效期内的中小学教师资格考试合格证明或《师范生教师职业能力证书》并签订承诺书，承诺在2026年8月31日前取得与应聘岗位相符的教师资格证。报考体育教师岗位的考生需提供学院出具的篮球、足球、田径、跆拳道及武术专项证明或相关佐证材料。不纳入招聘范围：惠城区在职在编教师；已参加2026年惠州市市直学校、各县（区）公办学校公开招聘编内教师并进入体检环节的人员等。",
