  "enroll": "2026年5月19日8:30至5月25日17:30（登录全国事业单位招聘网 http://www.qgsydw.com 或“事招雷达APP”报名，每人限报一个岗位）；笔试确认时间2026年5月26日8:30至5月27日17:30",
  "exam": "发布公告→网上报名→资格初审→笔试确认→打印准考证→笔试（2026年5月30日下午3:00-4:30，闭卷，考查教育综合能力（综合卷），满分100分，合格线60分）→现场资格复审→面试（“试讲”，备课20分钟、试讲10分钟，满分100分，合格线70分）→体检→选岗→考察→公示→聘用；考试总成绩=笔试成绩×50%+面试成绩×50%",
  "condition": "招聘对象为符合招聘岗位及资格条件的2026届高校毕业生、社会人员、退役军人均可报考。2026届高校毕业生须于2025年9月1日至2026年8月31日期间取得毕业证书、学位证书及岗位要求的其他证明材料；在国（境）外取得本科学历及学士学位以上的，还须于2026年8月31日前取得中国教育部留学服务中心出具的国（境）外学历学位认证证书。其他应聘人员须于面试资格复审前取得相应毕业证书、学位证书及岗位要求的其他证明材料。具体资格条件：（1）具有普通高校本科及以上学历并取得学士及以上学位；（2）符合应聘岗位相关专业（代码）要求，专业名称及代码参照《广东省2026年考试录用公务员专业参考目录》，所学专业以所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；（3）取得与应聘岗位相应的教师资格证，暂未取得教师资格证书的2026届高校毕业生可提供有效期内的《师范生教师职业能力证书》或《中小学教师资格考试合格证明》，拟聘用人员必须在2026年8月31日前取得相应学段学科的教师资格证，逾期取消聘用资格；（4）年龄、工作时间等时间计算截至2026年5月31日。报考B类岗位有要求师范类专业的须提供师范生证明；不得报考人员含仲恺高新区在编教职员及已参加仲恺高新区2026年赴高校招聘并签订就业协议的人员。获聘人员须与仲恺高新区教育文化卫生健康局签订任教协议书，自办理人事关系起须在受聘单位服务不少于5年。港澳居民可报名。",
