  "exam": "网上报名→网上初审→发布笔试考试通知（考生网上确认参加考试并打印准考证）→笔试（初定5月30日；报考心理、体育、音乐、美术、学前教育、不限专业等岗位笔试内容主要测试教育综合知识，其他岗位为学科知识和教育综合知识相结合，满分100分、合格线60分）→现场资格审核→面试（试讲；不限专业岗位采取结构化面试，满分100分、合格线60分）→体检→审档考察→公示→聘用；总成绩=笔试×50%+面试×50%",
  "condition": "招聘对象为符合招聘岗位和资格条件的普通高校应、往届毕业生。2026届高校毕业生须在2025年9月1日至2026年8月31日期间取得学历、学位证书；在国（境）外取得本科学历及学士学位以上的，还须于2026年8月31日前取得中国教育部留学服务中心出具的国（境）外学历学位认证证书。基本条件：具有中华人民共和国国籍；具有招聘岗位所要求的专业和技能条件；身体健康，具有适应岗位要求的身体条件和心理条件。年龄、工作时间等时间计算截至2026年5月18日（如“38周岁以下”应为1987年5月19日以后出生）。考生所学专业未列入《广东省2026年考试录用公务员专业参考目录》或无专业代码的，可选择目录中的相近专业报考。教师资格证：2026年应届毕业生如未取得《教师资格证》的，请提供有效期内《中小学教师资格考试合格证明》，属于师范生免试认定改革范围的教育类研究生、师范生须提交相应证明资料；2026年应届毕业生必须在2026年8月31日前取得教师资格证才能办理聘用手续，报考职业中学岗位的可放宽至两年内取得。在读的非2026年应届普通高等院校毕业生、现役军人、机关事业单位试用期未满的在编在职（岗）人员、惠东县在职在编教师、已通过惠东县教育局2026年校园招聘考试的拟聘人员不在本次招聘范围内。高中、职业中学和义务教育学段获聘人员为公益一类事业单位事业编制，幼儿园获聘人员为公益二类事业单位事业编制。签订聘用合同后五年内不得调离招聘岗位。",
