  "condition": "招聘对象为普通高校毕业生和其他具有国家承认学历学位的毕业生。其中：（一）2026届国内普通高校毕业生（非在职）须于2026年8月31日前取得相应毕业证书、学位证书、教师资格证书及岗位要求的其他证明材料；（二）港澳学习、留学归国人员须在报名首日前（即2026年4月9日前）取得相应毕业证书、学位证书、教师资格证书、教育部所属相关机构出具的国（境）外学历学位认证函及岗位要求的其他证明材料；（三）其他应聘人员须在报名首日前（即2026年4月9日前）取得相应毕业证书、学位证书、教师资格证书及岗位要求的其他证明材料。其他说明：年龄要求应聘者年龄须在18至38周岁（即1987年4月9日至2008年4月9日期间出生）；学历、学位、专业、执业资格要求详见《广东省江门市蓬江区2026年教师招聘（本地专场）岗位表》（附件1），如初中物理教师岗位要求本科以上学历、学士以上学位，本科专业物理学类（B0702）、研究生专业物理学（A0702）或学科教学硕士（专业硕士）（A040113），取得相应学科初中或高中教师资格证，报考学科须与所学专业一致，以研究生学历报考的本科与研究生阶段所学专业须相同或相近。教师资格证：2026届毕业生暂未取得的，需提交《中小学教师资格考试合格证明》或《师范生教师职业能力证书》和《关于按期取得教师资格证的承诺书》（附件3）。聘用人员应在本区公办学校服务不少于5年，须服从“县管校聘”统筹调配管理。港澳居民符合条件的可报考。",
