  "condition": "招聘对象为“应届毕业生”“社会人员”“不限”三类。“应届毕业生”指纳入普通高等院校统一招生计划的普通高等院校2026年应届毕业生（非在职），且须于2026年8月31日前取得招聘岗位要求的学历学位证书；港澳学习、留学归国人员报名的，报名时毕业未满1年的视为应届毕业生。“社会人员”指除应届毕业生外，于报名首日前（即2026年3月3日前）已取得国家承认学历学位的人员。“不限”即同时面向“应届毕业生”和“社会人员”两种对象招聘。招聘条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好政治素质和道德品行；具有适应岗位要求的身体条件和心理素质，无精神病史；招聘公告要求的其他条件。学历、学位、专业要求：应聘人员应具备招聘岗位所要求专业的学历学位，按照《广东省2026年考试录用公务员专业参考目录》（附件2）设置岗位专业条件，应聘人员毕业证书所列专业应与岗位要求一致；所学专业未列入专业目录的可选择相近专业报考，须提供经毕业院校或该院校教务处盖章确认的专业课程成绩单及专业相近意见材料；应聘人员学位种类、学校院系种类、毕业证上专业名称后括号内培养方向均不能作为报名专业依据。广东省江门市新会区教育系统2025年赴高校公开招聘事业编制教师（第三场）通过体检进入后续环节的应聘人员，不得再次报名参加本场考试。聘用人员应在江门市新会区教育系统服务不少于5年。获聘人员为事业单位编制人员。",
