  "condition": "招聘对象分“应届毕业生”“社会人员”“不限”等三类。其中“应届毕业生”的具体范围如下：1.国家统一招生的2026年普通高等院校应届毕业生（非在职），且须于2026年8月31日以前取得相应毕业证书、学位证书；2.国家统一招生的2024、2025届普通高校毕业生（非在职）未落实工作单位的人员；3.2024年1月1日至2026年3月19日期间取得国（境）外学历学位且未落实工作单位的留学回国人员，并在规定时间内完成教育部门认证；4.正在参加或服务期满且考核合格后2年内的基层服务项目人员。“社会人员”指除应届毕业生外，于报名首日前已取得国家承认学历学位的人员。“不限”指同时面向“应届毕业生”和“社会人员”两类招聘对象。招聘条件：具有中华人民共和国国籍，享有公民政治权利，遵守宪法和法律；具备良好的品行和职业道德，热爱教育事业，身心健康；具备履行岗位职责的身体条件，身体状况符合《广东省教师资格申请人员体格检查标准（2013年修订）》，无精神病史；具备岗位所需的专业、能力及技能条件；报考年龄为18周岁至35周岁（即1990年3月19日至2008年3月19日期间出生），部分岗位年龄条件若符合岗位要求可适当放宽，具体详见岗位表。获聘人员为江海区事业单位编制人员。",
