  "condition": "报考条件：（一）基本资格条件：1.具有中华人民共和国国籍；2.遵守宪法和法律；3.拥护中国共产党领导和社会主义制度；4.具有良好政治素质和道德品行；5.适应岗位要求的身体条件；6.招聘岗位要求的其他条件，详见《2026年上半年台山市部分学校公开招聘教师岗位表》。年龄须年满18周岁（即2008年3月30日以前出生）；年龄要求只针对社会人员，应届毕业生不受年龄限制。（二）招聘对象分为“应届毕业生”“社会人员”和“不限”：“应届毕业生”指普通高等院校、职业院校（含技工院校）2026年应届毕业生（非在职），国内普通高等院校、职业院校（含技工院校）2026年应届毕业生（非在职）须于2026年8月31日前取得相应毕业证书、学位证书及岗位要求的其他证明材料，在境内就读的中外合作办学2026年应届毕业生（非在职）须于2026年12月31日前取得相应毕业证书、学位证书及岗位要求的其他证明材料；“社会人员”指除应届毕业生外，须于报名首日（2026年3月31日）前已取得国家承认学历的人员；“不限”含应届毕业生和社会人员。港澳台学习、留学归国人员报考前须取得相应学历学位。（三）岗位专业、学历、学位、教师资格及其他条件：如台山市第一中学高中语文专任教师（应届毕业生岗位）要求本科以上学历、学士以上学位，研究生专业教育学（A0401）、中国语言文学（A0501）、学科教学硕士（专业硕士）（A040113），本科专业教育学类（B0401）、中国语言文学类（B0501），须取得相应学段以上的教师资格；高中生物专任教师岗位（不限对象）要求博士研究生学历，免笔试直接面试。获聘人员为事业单位编制人员。",
