  "title": "深圳市公办中小学2025年12月面向2026年应届毕业生公开招聘教师公告",
  "posts": "全市公办中小学（含市属学校及各区属学校）各学科教师岗位",
  "count": "888",
  "staffing": "事业编",
  "enroll": "2025年12月27日10:00-2026年1月5日18:00（网上报名系统 https://bm.gd-pa.cn/dzsys/szjs ）；现场宣讲及咨询：2025年12月27日9:30-17:00、12月28日9:30-16:00，深圳市福田区会展中心1号馆",
  "exam": "先笔试后面试；笔试2026年1月17日（星期六）在深圳市进行，考一科（客观题，各岗位笔试内容见岗位表），成绩占40%；面试总分100分、合格线70分，成绩占60%；综合成绩=笔试40%+面试60%",
  "condition": "招聘对象：2025年9月1日-2026年8月31日期间毕业的2026年高校应届毕业生（非在职）；正在参加或服务期满且考核合格后2年内的基层服务项目人员；2026年毕业的定向生、委培生原则上不得报考。报考学历：具有普通高校（非在职）本科及以上学历，并具有相应学位；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求，必须具备高学历相应的学位。报考专业：应聘人员所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；专业条件参照《广东省2026年考试录用公务员专业参考目录》设置；所学专业未列入目录（无专业代码）的可选择相近专业报考，必修课程须与岗位要求专业的主要课程基本一致；所学专业必须与岗位要求的学历层次相对应。报考年龄：以《招聘岗位表》中“与岗位有关的其它条件”要求为准，计算截止时间为本次招聘报名首日（38岁以下即1986年12月27日以后出生；40岁以下即1984年12月27日以后出生；43岁以下即1981年12月27日以后出生）。教师资格证书：岗位表“与岗位有关的其它条件”中有教师资格证要求的按岗位表要求报考；没有要求的，报名时需提供与岗位对应学科且不低于岗位学段层次的教师资格证（报考高中语文需高中语文教师资格证；报考中学语文、初中语文需初中及以上语文教师资格证，仅有小学语文教师资格证为不符合条件；报考中小学语文、小学语文需小学及以上语文教师资格证）；如报名时未取得的，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名，但须承诺于2027年8月31日前取得相应层次及学科的教师资格证书，到期未取得者取消聘用资格。其他证书：岗位要求取得其他资格证书的须于报名首日前取得；外语专业八级证书暂未取得的须承诺于2026年8月31日前取得。不得报名情形：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；未按规定履约任教的公费师范生；法律法规规定的其他情形。",
