  "staffing": "事业编",
  "enroll": "2026年3月12日9:00-2026年3月18日16:00（报名系统 https://www.qgsydw.com/xxywzlzt/bmzl/zxsnsq ）；笔试网上确认2026年3月23日9:00-18:00",
  "exam": "先笔试后面试；笔试2026年3月28日在西安，A卷（学科专业知识+行政能力测试，适用高中语文/数学/英语/物理/历史/生物）、B卷（教育学、心理学和行政能力测试，适用初中信息技术），满分100分占综合成绩40%；面试满分100分、合格线70分，占60%；综合成绩=笔试40%+面试60%",
  "condition": "招聘对象：2025年9月1日至2026年8月31日期间毕业的普通高等学校毕业生（非在职）；参加服务西部计划的大学生志愿者及“三支一扶”高校毕业生，此前无工作经历的，服务期满且考核合格后2年内可报考；定向生限在定向地区报考，委培生原则上不得报考。报考学历：具有普通高校（非在职）本科及以上学历，并具有相应学位；低学历不能报考要求高学历的岗位，高学历可以报考要求低学历的岗位，但必须具备高学历相应的学位。报考专业：所学专业必须符合岗位要求，以所获毕业证书上的专业为准，参考《广东省2026年考试录用公务员专业参考目录》；专业未列入目录的可按相近专业报考（必修课程基本一致），报名时须提供专业比对材料；所学专业必须与岗位要求的学历层次相对应；考生必须以应届毕业学历专业报考。报考年龄：最高年龄限制统一为38周岁（1987年3月12日之后出生）。教师资格证：所有考生报名时均须提供相应层次的教师资格证——小学岗位须具备小学及以上教师资格证，初中岗位须具备初中及以上教师资格证，高中岗位须具备高中（中职）及以上教师资格证，中职岗位须具备中职（高中）及以上教师资格证；报名时暂无法提供的，须本人承诺于2027年8月31日前取得相应层次的教师资格证，到期未取得者取消聘用资格；所有考生均须取得教师资格证后方可办理聘用备案手续。考生须在2026年8月31日前取得符合报考要求的毕业证、学位证。",
