  "enroll": "2026年4月29日-5月8日18:00（报名系统 https://bm.gd-pa.cn/dzsys/szlh ）；笔试线上确认5月12日8:00-5月13日14:00",
  "exam": "先笔试后面试；笔试2026年5月16日（暂定）在深圳市，专业能力笔试为客观题（教育学、心理学、行政职业能力测验（言语理解与表达、判断推理）、时事政治及教师综合素养等），占40%；面试满分100分、个人面试成绩当场公布，占60%，面试合格线70分",
  "condition": "招聘对象：2025年9月1日至2026年8月31日期间毕业的普通高等学校毕业生（非在职）；正在参加或服务期满且考核合格后2年内的基层服务项目人员；定向生限参加定向地区的招考，委培生原则上不得报考。报考学历：具有普通高校（非在职）本科及以上学历，并具有相应学位；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求，必须具备高学历相应的学位；研究生学历报考的，除符合专业要求外，还应具有和研究生专业对应的学位。报考专业：所学专业须与岗位要求的专业相符，参考《广东省2026年考试录用公务员专业参考目录》；岗位表专业要求为“学科门类”（2位数）的，所学专业为该学科门类所含“学科”（4位数）或“专业”（6位数）均符合；所学专业未列入目录的可按相近专业报考（必修课程70%以上相近），须提供课程成绩单、课程对比情况说明等材料；第二学位取得符合专业要求的毕业证和学位证可以该专业报考。报考年龄：最高年龄限制为38周岁（即1987年4月29日之后出生）。职业资格：教师资格证——报名时须提供与岗位对应学科且不低于岗位层次的教师资格证（报考高中语文需高中语文教师资格证；报考初中语文需初中或以上语文教师资格证，仅有小学语文教师资格证为不符合条件；报考小学语文需小学及以上语文教师资格证），报名时未取得的考生，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名，但须承诺于2027年8月31日前取得相应层次及学科的教师资格证书，到期未取得者取消聘用资格；其他证书如岗位要求取得的须于报名首日前取得，外语专业八级证书暂未取得的须承诺于2026年8月31日前取得。不予接受报考：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；未完成教学大纲规定学习内容的结业生、肄业生；非地方班的军队院校应届毕业生；现役军人；未按规定履约任教的公费师范生；法律法规规定的其他情形。",
