  "enroll": "采取网上报名，2026年4月8日起登录招聘系统报名；西安考点报名截止2026年4月15日18:00，重庆考点报名截止2026年4月21日18:00；笔试网上确认：西安考点4月16日00:00-16:00、重庆考点4月22日00:00-16:00",
  "exam": "先笔试后面试；西安考点笔试初定2026年4月19日、重庆考点笔试初定4月25日，考一科（客观题，内容包括教育政策法规、教育基础理论、教师职业素养、教学实施要求、心理学等），满分100分按40%折算计入综合成绩，按拟聘用名额5倍确定入围面试人员；面试采用模拟讲课方式，成绩当场公布，合格线70分，占60%；综合成绩=笔试40%+面试60%",
  "condition": "招聘对象：2025年9月1日至2026年8月31日期间毕业的普通高等学校毕业生（非在职）；参加服务西部计划的大学生志愿者及“三支一扶”高校毕业生，此前无工作经历的，服务期满且考核合格后2年内可报考；定向生限参加定向地区的招考，委培生原则上不得报考。报考人员身份：毕业生均指纳入普通高校统一招生计划并通过普通高等教育毕业的毕业生（非在职），留学归国人员报到时必须提供《国外学历学位认证书》。报考学历：均要求具有普通高校（非在职）本科及以上学历，并具有相应学位；以研究生学历报考的，需同时具有本科毕业证、学位证；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位但必须符合岗位的专业要求并具备高学历相应的学位。报考专业：所学专业须与岗位要求的专业相符，参考《广东省2026年考试录用公务员专业参考目录》；所学专业未包含在目录中的，与岗位要求专业必修课程70%以上相近视为相符，需提供学历证书及成绩单、课程对比情况说明及毕业院校设置专业的依据等材料；所学专业必须与岗位要求的学历层次相对应；所学专业按毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据。报考年龄：最高年龄限制统一为40周岁以下（即1985年4月8日之后出生）。教师资格证：所有考生报名时需提供与岗位对应学科且不低于岗位层次的教师资格证（报考高中语文需高中语文教师资格证；报考初中语文需初中或以上语文教师资格证，仅有小学语文教师资格证为不符合条件；报考小学语文需小学及以上语文教师资格证）；如报名时未取得的，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名，但须承诺于2027年8月31日前取得相应层次及学科的教师资格证书，到期未取得者取消聘用资格。外语岗位专业资格：报考英语教师岗位的考生须提供全国高校英语专业八级证书或雅思7.5分（含）及以上成绩单或托福100分（含）及以上成绩单；报名时未取得的可先报名，但须承诺在2026年8月31日前取得，未在规定时间取得的取消聘用资格。",
