  "exam": "先笔试后面试；笔试2026年4月18日在深圳市光明区，考一科，语文、数学岗位笔试内容为教育学、心理学、时事政治、学科专业等知识，其他岗位为教育学、心理学、行政职业能力测验（言语理解与表达、判断推理、数量关系等）、时事政治等相关知识；满分100分占40%，按拟聘人数3倍确定入围面试人员；面试满分100分、合格线70分，占60%；综合成绩=笔试40%+面试60%",
  "condition": "招聘对象：2025年9月1日至2026年8月31日期间毕业的普通高等学校毕业生（非在职）；正在参加或服务期满且考核合格后2年内的基层服务项目人员可报考；2026年毕业的定向生、委培生原则上不得报考。报考人员身份：毕业生均指纳入普通高校统一招生计划并通过普通高等教育毕业的毕业生（非在职），留学归国人员报到时必须提供教育部留学服务中心出具的《国外学历学位认证书》。报考学历：具有普通高校（非在职）本科及以上学历，并具有相应学位；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求并具备高学历相应的学位；以研究生学历报考的除符合专业要求外还应具有和研究生专业对应的学位。报考专业：所学专业须与岗位要求的专业相符，参考《广东省2026年考试录用公务员专业参考目录》；专业未列入目录的可按相近专业报考，所学专业与岗位要求专业必修课程70%以上相近视为相符，需提供成绩单进行判定；国（境）外学历需提供成绩单、课程比对情况说明及中文翻译文件；所学专业必须与岗位要求的学历层次相对应；本科专业为“教育学类”（B0401）或研究生专业为“教育学”（A0401）的，需提供所在院系出具的专业研究方向与岗位要求学科一致的证明并提供成绩单。报考年龄：38周岁以下（年龄计算截止时间为本次招聘报名首日）。教师资格证：所有应聘人员报名时需提供与岗位对应学科且不低于岗位层次的教师资格证（报考高中语文岗位需提供高中语文教师资格证；报考初中语文岗位需提供初中或以上语文教师资格证，仅有小学语文教师资格证则为不符合条件；报考小学语文岗位需提供小学及以上语文教师资格证）；如报名时暂无法提供，须提交承诺书，承诺于2027年8月31日前取得相应层次及学科的教师资格证书，届时无法提供的将取消聘用资格；所有拟聘人员在办理聘用手续前均须取得相关教师资格证书，未取得教师资格证不予办理聘用手续。",
