  "enroll": "2026年6月1日9:00-6月5日16:00（报名系统 https://psjy2026.htirc.cn/ ）；参加笔试确认6月9日9:00-17:00；打印准考证6月12日9:00后",
  "exam": "先笔试后面试；笔试2026年6月14日现场笔试，为客观题，测试内容为教育学、心理学、行政职业能力测验和时事政治等相关知识，满分100分，按拟聘人数3倍确定入围面试人员；面试满分100分、成绩当场公布，面试合格线与综合成绩合格线由坪山区教育局划定；综合成绩=笔试40%+面试60%（综合成绩合格线66分，面试合格线70分，见后续公告）",
  "condition": "招聘对象：2025年9月1日至2026年8月31日期间毕业的普通高等学校毕业生（非在职）；参加服务西部计划的大学生志愿者及“三支一扶”高校毕业生，此前无工作经历的，服务期满且考核合格后2年内可报考；定向生限参加定向地区的招考，委培生原则上不得报考。报考人员身份：毕业生均指纳入普通高校统一招生计划并通过普通高等教育毕业的毕业生（非在职），留学归国人员报到时必须提供《国外学历学位认证书》。报考学历：低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求并具备高学历相应的学位；研究生学历报考的，除符合专业要求外还应具有和研究生专业对应的学位。报考专业：所学专业须与岗位要求的专业相符，参考《广东省2026年考试录用公务员专业参考目录》；岗位条件对所学专业或与岗位有关的其他条件有方向要求的，考生须符合具体方向方可报考，需所在院系出具专业研究方向与岗位要求一致的证明并提供相关佐证材料（如专项等级证书、专项获奖证书等），若成绩单已有明确体现专业方向则无需提供；所学专业未列入目录（无专业代码）的，与岗位要求专业必修课程70%以上相近视为相符，可按相近专业报考并提供毕业证书、成绩单、课程对比情况说明、毕业院校设置专业的依据等材料；所学专业必须与岗位要求的学历层次相对应。报考年龄：本科、硕士研究生学历要求38周岁以下，博士研究生学历要求43周岁以下。职业资格：报考者须取得相应教师资格证，报名时未取得的考生，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平等要求的，可先报名，但须承诺于2027年8月31日前取得相应教师资格证书，到期未取得者取消聘用资格。其他：社保存在“挂靠”形式的不能入职，在校就读期间（含未毕业的实习）参加社会保险或毕业后挂靠参保的，须于2026年7月1日前完成退保后方能办理入职聘用手续。",
