  "title": "深圳中学2026年3月面向2026年应届毕业生公开招聘教师公告",
  "posts": "深圳中学（涵盖初中、高中学段）高中教师：语文、数学、化学、体育（篮球）；初中教师：语文、物理、信息科技、体育（乒乓球、排球）；竞赛教练：数学、物理、信息学",
  "count": "13",
  "staffing": "事业编",
  "enroll": "网上报名2026年3月13日9:00至3月20日16:00（网址 http://recruit.shenzhong.net/ ）；现场报名2026年3月23日上午9:30-11:00北京师范大学京师大厦就业中心多功能厅101、3月23日14:30-16:00北京大学英杰交流中心第八会议室；资格初审2026年3月16日至3月23日",
  "exam": "先笔试后面试；笔试预计2026年3月24日在北京，闭卷，考一科（客观题+主观题，内容为学科专业知识），满分100分、合格线60分，按岗位拟聘人数3倍确定入围面试人员；面试分专业面试和综合面试，预计3月26-27日在北京，专业面试满分100分合格线70分（占成绩20%）、综合面试满分100分合格线70分（占30%）；总成绩=笔试50%+专业面试20%+综合面试30%，总成绩合格线70分",
  "condition": "招聘对象：2025年9月1日-2026年8月31日期间毕业的2026年高校应届毕业生（非在职）；正在参加或服务期满且考核合格后2年内的基层服务项目人员；2026年毕业的定向生、委培生原则上不得报考。报考学历：具有普通高校（非在职）研究生学历，并具有相应学位；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求并具备高学历相应的学位。报考专业：所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；专业条件参照《广东省2026年考试录用公务员专业参考目录》设置；岗位表专业要求为“学科门类”（2位数）的，所学专业为该学科门类所含“学科”（4位数）或“专业”（6位数）均符合；专业未列入目录（无专业代码）的可选择相近专业报考，必修课程须与岗位要求专业的主要课程基本一致，报名时须提供毕业证书、成绩单、课程对比情况说明及毕业院校设置专业的依据等材料；所学专业必须与岗位要求的学历层次相对应。报考年龄：40岁以下（截至公告报名首日，即1985年3月13日以后出生）。教师资格证：报名时需提供与岗位对应学科且不低于岗位学段层次的教师资格证（报考高中语文教师岗位需提供高中语文教师资格证；报考初中语文教师岗位需提供初中及以上语文教师资格证，仅有小学语文教师资格证则为不符合条件）；如报名时未取得的，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名，但须承诺于2027年8月31日前取得相应层次及学科的教师资格证书，到期未取得者取消聘用资格；其他证书如岗位要求取得的须于报名首日前取得。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；未按规定履约任教的公费师范生；法律法规规定的其他情形。",
