  "title": "深圳市第二特殊教育学校2026年6月面向2026年应届毕业生公开招聘教师公告",
  "posts": "深圳市第二特殊教育学校（深圳市教育局直属公办特殊教育寄宿制高中，承担智力残疾、孤独症、多重残疾等类型高中阶段特殊学生教育）特殊教育学科教师",
