  "enroll": "线上报名2026年7月2日0:00-7月9日12:00（材料发送至邮箱 ssses2021@163.com ）；现场报名2026年7月9日上午9:00-12:00，湖南师范大学国际学术交流中心5楼会议室（长沙市岳麓区岳山南路36号）",
  "exam": "先笔试后面试；笔试2026年7月9日在长沙市，闭卷，考1科（主观题，内容为学科专业知识、教育基础理论、教师职业素养、教学实施要求、心理学等），总分100分、合格线60分，按岗位拟聘人数5倍确定入围面试人员；面试形式为结构化面试，2026年7月10日在长沙市组织，总分100分、合格线70分；综合成绩=笔试40%+面试60%",
  "condition": "招聘对象：2025年9月1日-2026年8月31日期间毕业的2026年高校应届毕业生（非在职）；正在参加或服务期满且考核合格后2年内的基层服务项目人员；2026年毕业的定向生、委培生原则上不得报考。报考学历：具有普通高校（非在职）研究生学历，并具有相应学位；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求并具备高学历相应的学位（如岗位要求学历为“研究生”，专业为“数学”，本科专业为“数学”但研究生专业为“物理”，则不符合要求）。报考专业：所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；专业条件参照《广东省2026年考试录用公务员专业参考目录》设置；岗位表专业要求为“学科门类”（2位数）的，所学专业为该学科门类所含“学科”（4位数）或“专业”（6位数）均符合；专业未列入目录（无专业代码）的可选择相近专业报考，必修课程须与岗位要求专业的主要课程基本一致，报名时须提供毕业证书、成绩单、课程对比情况说明及毕业院校设置专业的依据等材料；所学专业必须与岗位要求的学历层次相对应。报考年龄：在《招聘岗位表》“与岗位有关的其它条件”中有年龄限制要求的按岗位表要求报考；其他条件中没有年龄要求的，报考的年龄均要求为40周岁以下（截至公告报名首日）。教师资格证：按《招聘岗位表》中“与岗位有关的其它条件”要求的教师资格证书报考，报名时需提供教师资格证，该证书的学段层次不得低于报考岗位的学段要求，且学科须与岗位表中对教师资格证学科的要求一致（如报考高中语文教师岗位的需提供高中语文教师资格证；报考中小学语文教师岗位的需提供初中及以上语文教师资格证，仅有小学语文教师资格证则为不符合条件）；如报名时未取得的，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名，但须承诺于2027年8月31日前取得相应层次及学科的教师资格证书，并提交《未取得教师资格证报考人员承诺书》，到期未取得者取消聘用资格。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；未按规定履约任教的公费师范生；法律法规规定的其他情形。",
