  "condition": "招聘对象：2025年9月1日至2026年8月31日期间毕业的2026年高校应届毕业生（非在职）；正在参加或服务期满且考核合格后2年内的基层服务项目人员；2026年毕业的定向生、委培生原则上不得报考。报考学历：具有普通高校（非在职）研究生学历，并具有相应学位；低学历不能报考高学历要求的岗位，高学历可以报考低学历要求的岗位，但必须符合岗位的专业要求并具备高学历相应的学位。报考专业：应聘人员所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据；招聘岗位中专业条件参照《广东省2026年考试录用公务员专业参考目录》设置；岗位表中“专业”要求为“学科门类”（2位数）的，所学专业为该学科门类所含“学科”（4位数）或“专业”（6位数）均符合；专业未列入目录（无专业代码）的可选择相近专业报考，所学专业必修课程须与招聘岗位要求专业的主要课程基本一致，并在报名时提供毕业证书、成绩单、课程对比情况说明及毕业院校设置专业的依据等材料；第二学位取得符合岗位专业要求的毕业证书和学位证书可以该专业报考；所学专业必须与岗位要求的学历层次相对应。报考年龄：40岁以下（截至公告报名首日，即1985年3月17日以后出生）。教师资格证：在《招聘岗位表》“与岗位有关的其它条件”中有教师资格证要求的按岗位表要求报考；岗位条件中没有教师资格证要求的，报名时需提供与岗位对应学科且不低于岗位学段层次的教师资格证（例如报考高中语文教师岗位的需提供高中语文教师资格证）；如报名时未取得的，符合教师资格考试报名条件和教师资格认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名，但须承诺于2027年8月31日前取得相应层次及学科的教师资格证书，到期未取得者取消聘用资格。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；未按规定履约任教的公费师范生；法律法规规定的其他情形。港澳居民符合《粤港澳大湾区（内地）事业单位公开招聘港澳居民管理办法》（粤人社规〔2021〕34号）及公告规定的可报考。",
