  "posts": "珠海市第二中学、珠海市第一中学平沙校区、珠海市广东实验中学金湾学校、珠海市艺术高级中学、珠海市实验中学、珠海市斗门第一中学、珠海市鸿鹤中学、珠海市麒麟中学、珠海市田家炳中学、珠海市和风中学、珠海市第四中学、珠海市第三中学、珠海市第一中等职业学校、珠海市理工职业技术学校",
  "count": "68（共10个职位）",
  "staffing": "事业编",
  "enroll": "2026年9月14日9:00至2026年9月18日12:00（珠海市教育局官网“教师招聘网上报名系统”）",
  "exam": "网上报名—资格初审—笔试（测评基本能力，满分100分，合格线60分，安排在珠海，预计9月19日）—资格复审—心理品质测试—面试（“试讲或说课（技能测试）+答辩”，满分100分，合格线70分）；综合成绩=笔试成绩×40%+面试成绩×60%",
  "condition": "招聘对象为符合招聘岗位资格条件的2027年应届毕业生，具体为：（1）2026年9月1日至2027年8月31日期间取得国内普通高等院校2027年研究生学历、硕士及以上学位的应届毕业生（非在职）；（2）同期取得在境内就读的中外合作办学2027年研究生学历、硕士及以上学位的应届毕业生（非在职），学位证书须于2027年12月31日前取得；（3）同期取得国（境）外研究生学历、硕士及以上学位及教育部中国留学服务中心国外学历学位认证书的留学回国人员（非在职）；（4）正在参加或服务期满且考核合格后2年内的服务基层项目人员。符合报考条件的2027届珠海市生源公费师范毕业生可不受报考岗位的学历学位要求限制，但专业或专业方向须与招聘岗位一致。学历要求研究生、学位要求硕士及以上，专业须符合岗位专业要求（参照广东省2026年考试录用公务员专业参考目录，如高中心理岗位要求心理学A0402）。年龄38周岁以下（1987年9月14日以后出生）。报名时原则上需提供相应层次相应学科的教师资格证；暂未取得教师资格证的2027届毕业生可持有效期内的《中小学教师资格考试合格证明》报名应聘，免试认定改革的教育类研究生和师范生可提交有效期内的《师范生教师职业能力证书》或院校证明，拟聘用人员必须在2027年8月31日前取得教师资格证书，逾期取消聘用资格。事业单位在编人员及珠海市内事业单位工作人员须提供用人单位同意报考证明。最低工作服务年限5年（含试用期）。港澳居民按粤人社规〔2021〕34号执行。",
