  "condition": "设A、B两类岗位。A类：符合招聘岗位条件的本科学士及以上学历学位的2026年应届毕业生，年龄38周岁及以下（1987年1月4日以后出生），其中：（1）国内普通高等院校毕业生（非在职）须于2025年9月1日至2026年8月31日期间取得相应毕业证书、学位证书；（2）在境内就读的中外合作办学毕业生（非在职）须于2026年1月1日至2026年12月31日期间取得相应毕业证书、学位证书，仅颁发学位证书的须2026年12月31日前取得；（3）在国（境）外就读的毕业生须2026年1月1日至2026年12月31日期间取得相应证书及教育部中国留学服务中心出具的国外学历学位认证书。B类：符合招聘岗位条件的本科学士及以上学历学位人员，须于资格复审前取得符合报考岗位专业要求的毕业证书、学位证书；初中数学竞赛教练岗位年龄放宽至40周岁（1985年1月4日以后出生）。所学专业须符合岗位要求的专业；暂未取得教师资格证的需提交《中小学教师资格考试合格证明》或《师范生教师职业能力证书》，并签订《关于按期取得教师资格证的承诺书》。招聘人员最低工作服务年限5年（含试用期）。港澳居民可报考。",
