  "title": "“百万英才汇南粤”——珠海市金湾区面向2026年应届毕业生及社会人员公开招聘中小学编制内教师公告",
  "posts": "珠海市金湾区教育局下属初中和小学，在武汉、珠海设置考点，共招聘100名编制内教师（其中珠海考点招聘60名）",
  "count": "100（A类应届毕业生75人、B类社会人员25人）",
  "staffing": "事业编",
  "enroll": "2026年1月1日9:00至2026年1月8日18:00（报名网址 https://www.qgsydw.com/xxywzlzt/bmzl/zh26 珠海市金湾区事业单位报名系统）",
  "exam": "报名—资格初审—笔试确认—笔试（闭卷，主要测试基本能力，满分100分，合格线60分，武汉/珠海两考点线下笔试）—资格复审—心理测试—面试（“试讲+答辩”线下结构化，合格线70分，体育、美术、音乐、特殊教育岗位增加专业技能考试）；综合成绩：体育、美术、音乐、特殊教育岗位=笔试×40%+专业技能考试×30%+面试×30%，其他岗位=笔试×40%+面试×60%",
  "condition": "招聘对象为符合招聘岗位条件的两类人员，A类75人、B类25人，共100人。A类为符合招聘岗位条件的2026年应届毕业生，报考年龄18至38周岁（即1986年12月27日至2007年12月26日期间出生），具体为：（1）国家统一招生的2026年全国普通高校本科及以上学历、学士及以上学位的应届毕业生（非在职）；（2）2025年9月1日至2026年8月31日期间取得国（境）外本科及以上学历、学士及以上学位的毕业生，并于2026年8月31日前完成教育部留学服务中心学历学位认证；（3）在境内就读的2026届中外合作办学毕业生（非在职）须于2026年8月31日前取得相应毕业证书、学位证书及岗位要求的其他证明材料。B类为符合招聘岗位条件的社会人员，年龄18至38周岁，本科及以上学历、学士及以上学位，须于报名以前取得相应毕业证书、学位证书。考生报名时原则上需提供初级中学及以上层次和岗位学科的中学系列教师资格证（如报考中小学语文岗位均需具有初级中学及以上语文学科教师资格证）；A类应届毕业生暂未取得教师资格证的，符合教师资格考试报名条件和认定关于思想政治素质、普通话水平、身体条件等要求的，可先报名应聘，但须承诺于2026年8月31日前取得报考岗位要求的层次及学科教师资格证书。所有考生所学专业必须符合招考岗位专业要求方可报名（参照《广东省2026年考试录用公务员专业参考目录》，专业未列入参考目录的可按相近专业报考并提供课程对比说明）。A类岗位应届毕业生须以最高学历专业报考；符合报考条件的2026年珠海市生源教育部直属师范大学公费师范毕业生（北师大、华东师大、东北师大、华中师大、陕西师大、西南大学）可不受报考岗位的学历学位要求限制，但所学专业或专业方向须与招聘岗位（学科）要求一致，且笔试成绩不参加排名、直接进入资格复审。事业单位在编人员报考需提供用人单位同意报考证明。最低工作服务年限5年（含试用期）。港澳居民可报考。",
