  "condition": "招聘对象为：（1）符合招聘岗位条件的国内普通高等院校（含境内就读的中外合作办学）本科学士及以上学历学位的应届毕业生（非在职），须于2026年8月31日前取得相应毕业证书、学位证书；（2）符合招聘岗位条件的已取得国内普通高等院校（含境内就读的中外合作办学）本科学士及以上学历学位人员；（3）符合招聘岗位条件的已取得国（境）外本科学士及以上学历学位的人员，须有教育部留学服务中心出具的国外学历学位认证书。年龄38周岁及以下（1987年6月2日以后出生）。岗位资格条件：具体招聘学科岗位、人数、学历学位、专业要求等详见《珠海市斗门区2026年公开招聘公办中小学教师岗位表》，专业参照《广东省2026年考试录用公务员专业参考目录》；报考初中岗位须具有初级中学及以上教师资格证，报考小学岗位须具有小学及以上教师资格证；暂未取得教师资格证的应届毕业生，须于现场资格复审时提供相应层次有效期内的《中小学教师资格考试合格证明》或《师范生教师职业能力证书》，且须在2026年8月31日前取得相应层次教师资格证，逾期未取得取消聘用资格。不得报考情形含已签署公费定向培养协议且尚在服务期限内的毕业生、有违法犯罪记录不能通过入职教师岗位背景查询的等。港澳居民可报考。",
