  "title": "百万英才汇南粤—2026年上半年肇庆市教育系统事业单位公开招聘教师公告",
  "posts": "肇庆市部分公办中小学校（职业学校）教师47名（共39个职位），于2026年4月到河南省郑州大学、河南大学设点现场招聘，如肇庆市第一中学中学思政教师等",
  "count": "47（共39个职位）",
  "staffing": "事业编",
  "enroll": "网络报名：2026年4月10日9:00至4月16日16:00（事业单位招考网 https://bm.gd-pa.cn/dzsys/nyzq ）；校园招聘会现场报名及资格审核：郑州大学主（新）校区中心体育馆2026年4月18日上午9:00-12:00，河南大学金明校区图书馆前广场4月19日上午9:00-11:00",
  "exam": "网络报名/现场报名→现场资格审核（通过后方可参加考试）→笔试（2026年4月19日下午，考点河南大学金明校区，内容含行政职业能力测试、教育学、心理学等相关知识，闭卷，满分100分、合格线70分）→面试（2026年4月20日，采取“试讲+结构化”方式，满分100分、合格线70分）；考试综合成绩=笔试成绩×50%+面试成绩×50%，综合成绩合格线70分；面谈签约签订高校毕业生就业三方协议",
  "condition": "招聘对象为2026年应届毕业生（非在职），即于2026年1月1日至2026年12月31日期间取得学历、学位证书的毕业生（含持国（境）外学历学位证书人员）。其中2026届国内普通高校毕业生须于2026年8月31日前取得相应毕业证书、学位证书。报考人员条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件。岗位要求：学历要求本科以上、学位要求学士以上（如中学思政教师岗位本科专业为科学社会主义B030501、思想政治教育B030503、马克思主义理论B030504，研究生专业为政治学A0302、马克思主义理论A0305、课程与教学论A040102（政治方向）、学科教学硕士（专业硕士）A040113（政治方向））；年龄18-38周岁（硕士放宽到40周岁、博士放宽到45周岁）；执业（职业）资格要求高级中学相应学科教师资格，通过公开招聘的考生如未取得相应学科相应学段教师资格证，须签订承诺书并在2026年8月31日前取得，否则取消聘用资格；报考岗位要求普通话水平测试须达到二级甲等或以上的，未取得须签订承诺书并在2026年8月31日前取得。不得以非最高学历专业报考，必须以最高学历专业报考；定向生、委培生原则上不得报考；只能报考1个岗位。港澳居民毕业生符合粤人社规规定条件的可报考。本次招聘人员最低工作服务年限为五年（含试用期）。",
