  "posts": "广东肇庆中学（初高中教学）、肇庆中学附属小学（小学教学）、肇庆市正德学校（专门教育）共18个岗位招聘20人，含小学美术教师、小学心理健康教育教师、化学教师、物理教师、音乐教师等",
  "count": "20（18个岗位）",
  "staffing": "事业编",
  "enroll": "2026年3月17日9:00至3月23日16:00（“肇庆市事业单位报考系统” https://sydwbk.zqzhrs.cn:8081 ）；报名确认2026年3月24日9:00至3月25日16:00；准考证打印2026年3月27日9:00后",
  "exam": "网络报名→资格初审→报名确认→笔试（2026年3月28日，地点肇庆市端州区东岗东路5号广东肇庆中学（信安校区）；教师岗按岗设考，笔试内容主要包括岗位相关知识，闭卷，满分100分、合格线70分）→资格复审→面试（教师岗采取试讲方式，财务岗、校医岗采取业务考核方式，满分100分、合格线70分）→体检→考察→公示→聘用；考试总成绩=笔试成绩×40%+面试成绩×60%",
  "condition": "招聘对象为普通高校毕业生，本次公招岗位18个、公招20人。其中：2026届国内普通高校毕业生（非在职）须于2026年8月31日前取得相应毕业证书、学位证书及岗位要求的其他证明材料；在境内就读的2026届中外合作办学毕业生（非在职）须于2026年12月31日前取得相应毕业证书、学位证书及岗位要求的其他证明材料。符合以下其中一点的可报考考生类别条件为“应届毕业生”的岗位：（1）国家统一招生的2026届普通高校毕业生（非在职）；（2）国家统一招生的2024、2025届普通高校毕业生（非在职）未落实工作单位的人员；（3）2024年1月1日至2026年3月16日期间取得国（境）外学历学位且未落实工作单位的留学回国人员，并在规定时间内完成教育部门认证；（4）正在参加或服务期满且考核合格后2年内的基层服务项目人员。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件。学历要求本科及以上（如小学美术教师岗位本科专业美术学类B1304、设计学类B1305，研究生专业美术学A1304、设计学A1305；小学心理健康教育教师岗位本科心理学类B0712、研究生心理学A0402）。应聘人员须提交学历学位证书（境外学习的须取得教育部留学服务中心认证书）、教师资格证及岗位要求的其他证书、最高职称证书、教育教学类比赛获奖证书和其他荣誉证书（如有）；应聘人员年龄、工作经历和相关证明材料计算截止日期为报名首日的前一天。应届毕业生不得以非最高学历专业报考，必须以最高学历专业报考；定向生、委培生原则上不得报考。本次招聘人员最低工作服务年限为五年（含试用期）。港澳居民毕业生符合粤人社规规定条件的可报考相关岗位。",
