  "exam": "网络报名→系统自动初审→报名确认→打印准考证→笔试（内容为教育学、教育心理学、教育教学知识与应用等相关专业知识，闭卷，满分100分、合格线60分；同一岗位按招聘人数1:5比例确定入围面试人员）→资格复审→面试（采取模拟教学、结构化面试以及专业技能测试相结合方式，美术、音乐、体育、信息科技教师岗位须参加专业技能测试；不参加技能测试岗位面试成绩=模拟教学×70%+结构化×30%，美术/音乐/体育/信息科技岗面试成绩=模拟教学×50%+结构化×20%+专业技能测试×30%）→体检→考察→公示→聘用；考试综合成绩=笔试成绩×40%+面试成绩×60%",
  "condition": "本次公开招聘岗位49个，招聘人数75人，符合招聘岗位及资格条件的2026届高校毕业生（非在职）、社会人员均可报考。其中：（一）2026届国内普通高校毕业生（非在职）及在境内就读的2026届中外合作办学毕业生（非在职）须于2026年8月31日前取得相应毕业证书、学位证书及岗位要求的其他证明材料；（二）其他应聘人员须于面试资格复审前取得相应毕业证书、学位证书及岗位要求的其他证明材料；国（境）外取得学历学位人员需同步提供由国家教育部所属相关机构出具的国（境）外学历、学位认证函等有关证明材料；（三）港澳居民符合粤人社规〔2021〕34号和本公告规定相关条件的也可报名。其他报名条件：报考年龄18至38周岁（即1987年6月23日至2008年6月23日期间出生），博士研究生报考年龄放宽到40周岁；具备与教学岗位相对应的教师资格证，2026届国内普通高校毕业生（非在职）及在境内就读的2026届中外合作办学毕业生（非在职）报名时未取得岗位所要求的教师资格证，须签订承诺书并在2026年8月31日前取得，逾期无法提供的将取消聘用资格；应聘人员应具备与招聘岗位要求一致的学历、学位证书，所学专业按所获毕业证书上的专业为准，辅修专业、学位种类均不作为专业依据，须按《广东省2026年考试录用公务员专业参考目录》报考；研究生专业为“教育学（A0401）、课程与教学论（A040102）、学科教学硕士（专业硕士）（A040113）”、本科专业为“教育学（B040101）”的，专业研究方向须与岗位学科方向一致。如语文教师岗位要求本科及以上学历、学士及以上学位，专业为课程与教学论A040102、学科教学硕士（专业硕士）A040113、中国语言文学A0501、国际中文教育A040123、教育学B040101、中国语言文学类B0501，资格证书要求初级中学及以上教师资格。在编教师报考前须征得所在学校同意。本次招聘人员最低工作服务年限为五年（含试用期）。",
