  "exam": "网络报名→现场资格审核（合格发放准考证）→笔试（广西师大考点2026年4月8日13:00-17:00；华南师大考点4月11日13:00-17:00；内容主要包括岗位相关专业知识，闭卷，满分100分、合格线60分，按1:3确定入围面试人员）→面试（广西师大考点4月9日8:00-12:00；华南师大考点4月12日8:00-12:00；采取“试讲+答辩”方式，满分100分、合格线60分）→面谈与签约（签订高校毕业生就业三方协议）→体检→考察→公示→聘用；总成绩=笔试成绩×40%+面试成绩×60%",
  "condition": "招聘对象为普通高校2026年应届毕业生（非在职），即2026年1月1日至2026年12月31日期间取得学历、学位证书的毕业生（含持国（境）外学历学位证书人员）。其中2026届国内普通高校毕业生须于2026年8月31日前取得相应毕业证书、学位证书。港澳居民毕业生符合粤人社规〔2021〕34号和公告规定相关条件的可报考相关岗位。定向生、委培生原则上不得报考，如委培或定向单位同意其报考，应当由委培或定向单位出具同意报考证明，并经所在院校同意后方可报考。报考条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件。年龄条件：报考人员年龄在38周岁及以下（1987年3月27日及以后出生）。现场资格审核材料（2026届毕业生须提供）：《肇庆市高要区教育局2026年赴高等院校招聘教师报名表》；有效居民身份证；就业协议书或就业推荐表（研究生学历的考生还需提供本科学历及学位证书）；经教务处盖章的所学专业课程成绩单；教育部学籍在线验证报告（学信网打印）；个人简历；高中系列《教师资格证书》或有效期内的高中系列《中小学教师资格考试合格证明》（暂未取得请提供承诺书）。所学专业未列入《广东省2026年考试录用公务员专业参考目录》（无专业代码）的可选择相近专业报考，须提供课程成绩单、课程对比情况说明及毕业院校设置专业的依据等材料。本次招聘人员最低工作服务年限为五年（含试用期）。",
