  "condition": "本次招聘岗位8个，共招聘10名具有博士研究生学历或具有高级职称人员。其中，博士研究生为普通高校应届毕业生（非在职），须于2026年12月31日前取得学历学位证书；其他应聘人员须于面试资格复审前取得相应毕业证书及岗位要求的其他证明材料。港澳居民符合粤人社规和本公告规定相关条件的可报考相关岗位。定向生、委培生原则上不得报考。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件。报考人员应为1980年4月13日及以后出生的。现场审核材料须提供：《2026年肇庆市高要区教育局公开招聘教师报名表》；有效居民身份证；毕业证、学位证；教育部学籍在线验证报告（学信网打印）；个人简历；中小学系列《教师资格证书》；中小学系列《职称证书》。国（境）外学历、学位人员需提供由教育部留学服务中心出具的国（境）外学历、学位认证书。招聘岗位考生类别条件为“应届毕业生”的，应聘人员不得以非最高学历专业报考，必须以最高学历专业报考。获聘人员为事业单位编制人员，符合条件博士学历的人员按规定享受本区的相关人才优惠政策。",
