  "exam": "按A、B类岗位采取不同考试形式：A类岗位采取“直接业务考核”方式（招聘单位成立专家考核组，可单独选用或综合使用综合考核、试教、专业技能测试、纸笔考核等方式）；B类岗位采取“笔试+面试”方式，笔试为专业素养及能力测试（闭卷，满分100分、合格线60分），面试采用模拟教学（专业技能素养测试）+答辩形式（满分100分、合格线70分），考试综合成绩=笔试成绩×40%+面试成绩×60%，综合成绩合格分数线66分",
  "condition": "招聘对象：（一）普通高等院校2026年应届毕业生和社会上具有国家承认学历学位的人员；（二）港澳居民符合《广东省人力资源和社会保障厅粤港澳大湾区（内地）事业单位公开招聘港澳居民管理办法》和本招聘公告规定的可报考；（三）符合报考条件的中山市生源的公费师范毕业生可不受报考岗位的学历学位要求限制，但专业或专业方向须与招聘岗位一致。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件详见附件1-5。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；法律、法规规定的其他情形。报名要求：同一考点每人限报一个岗位，同时报考多个岗位者视为无效报名；未招满的部分岗位可以顺延到其他考点进行招聘；已通知入围体检环节的考生不可再参加其他考点的招聘。应届毕业生毕业时间：应在2025年9月1日至2026年8月31日期间取得相应毕业证书、学位证书；国（境）外取得学历学位人员报考应届毕业生岗位的，须于2025年9月1日至2026年8月31日期间取得相应学历学位，且于2026年12月31日前取得教育部留学服务中心出具的国（境）外学历学位认证函。专业要求：招聘岗位专业参照《广东省2026年考试录用公务员专业参考目录》设置，所学专业未列入专业目录（无专业代码）的可选择相近专业报考并按要求提供成绩单、课程对比说明等材料。教师资格证：专任教师、专业课教师岗位应聘人员报名时原则上需提供与学段相应或以上层次的教师资格证；暂未取得教师资格证书的2026年应届毕业生，可持有效期内的中小学教师资格考试合格证明报名应聘，如报名时无法提供，须承诺于2027年8月31日前取得与学段相应或以上层次的教师资格证。年龄：应届毕业生不受年龄限制，社会人员年龄要求详见附件。其他：事业单位聘用人员应在招聘单位服务不少于5年；拟聘人员名单在中山市人力资源和社会保障局政务网公示5个工作日。",
