  "condition": "招聘对象：（一）普通高等院校2026年应届毕业生和社会上具有国家承认学历的人员；（二）港澳居民符合《广东省人力资源和社会保障厅粤港澳大湾区（内地）事业单位公开招聘港澳居民管理办法》和本招聘公告规定的可报考。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件（详见附件1岗位表）。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；法律、法规规定的其他情形。报名资料：《广东省事业单位公开招聘人员报名表》（在报名系统上填报，须亲笔签字确认并上传）；有效期内的居民身份证、学历证书、学生证和《普通高校毕业生就业推荐表》（整本全页，已取得岗位要求的毕业证书学位证书者可不提供）；国（境）外取得学历学位人员须提供教育部留学服务中心出具的国（境）外学历学位认证函，暂未取得的需提供就读院校开具的在读专业名称、所修课程及毕业时间证明（同时提供中文翻译件）。岗位差异：本次招聘岗位中部分岗位仅面向社会人员且要求较高专业技术资格，例如小榄镇公办小学“道德与法治专任教师”（岗位代码2690303）招聘对象为社会人员，须具有中小学道德与法治副高级及以上教师专业技术资格或中小学德育副高级及以上教师专业技术资格，年龄45周岁以下。应届毕业生可报考的岗位、学历学位、专业及其他要求详见附件1岗位表。",
