  "condition": "招聘对象：（一）2026届普通高校毕业生及社会上具有国家承认本科以上学历的人员；（二）港澳人员符合《广东省人力资源和社会保障厅粤港澳大湾区（内地）事业单位公开招聘港澳居民管理办法》和本招聘公告规定的可报考。基本条件：具有中华人民共和国国籍；遵守中华人民共和国宪法和法律法规；拥护中国共产党领导和社会主义制度；具备良好的政治素质和道德品行；具有岗位所需的专业或技能条件；具有适应岗位要求的身体条件；具有相应教师资格证（2026届普通高校毕业生未取得相应教师资格的，可提供有效期内的中小学教师资格考试合格证明）；具有岗位所需要的其他条件。资格条件：1.具有大学本科及以上学历（应届毕业生应具有普通高等院校本科及以上学历、学士及以上学位）；2.所学专业须与所聘岗位专业要求相对应；若所学专业未列入《广东省2026年考试录用公务员专业参考目录》，可选择专业目录中的相近专业报考，所学专业必修课程须与招聘岗位要求专业的主要课程基本一致，在报名表填报专业代码时以“9999999”代替，并上传相关毕业证书（已毕业的）、所学专业课程成绩单（须教务处盖章）、院校出具的课程对比情况说明及毕业院校设置专业的依据等材料，由招聘单位判定是否符合报考要求；3.若报考岗位与所学专业不相符，但应聘学科教学业绩突出的（近五年内曾获镇（区）级以上（含）教学比赛一等奖以上奖励或教育教学类荣誉称号），或取得应聘学科中级及以上职称的，或具有应聘学科3年及以上教学经历的（以合同、社保和工作单位出具证明为准），可报考相关学科岗位；4.应届毕业生年龄不限，社会人员年龄在40周岁以下（1985年8月7日后出生），符合以下条件之一的可放宽至45周岁以下（1980年8月7日后出生）：具有中小学副高级及以上职称的等。薪酬待遇：按小榄镇合同制教师待遇标准执行。",
