  "condition": "招聘对象：（一）普通高等院校2026年应届毕业生和社会上具有国家承认学历学位的人员；（二）港澳居民符合《广东省人力资源和社会保障厅粤港澳大湾区（内地）事业单位公开招聘港澳居民管理办法》和本招聘公告规定的可报考。基本条件：具有中华人民共和国国籍；遵守宪法和法律；拥护中国共产党领导和社会主义制度；具有良好的政治素质和道德品行；适应岗位要求的身体条件；招聘公告要求的其他条件，详见附件1。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；法律、法规规定的其他情形。报名资料：《广东省事业单位公开招聘人员报名表》（附件2）；有效期内的居民身份证、学历学位证书、学生证和《普通高校毕业生就业推荐表》（已取得岗位要求的毕业证书学位证书者可不提供）；国（境）外取得学历学位人员须提供教育部留学服务中心出具的国（境）外学历学位认证函，暂未取得的需提供就读院校开具的在读专业名称、所修课程及毕业时间证明（同时提供中文翻译件）；岗位所要求的有关证书、证明材料。岗位条件（据岗位表）：语文专任教师（20260101）本科以上学历、学士以上学位，专业为中国语言文学类（B0501）、新闻传播学类（B0503）、教育学类（B0401）等，教育学类须为语文方向，应届毕业生年龄不限、社会人员38周岁以下；另设研究生学历、硕士以上学位岗位（十一级，要求研究生专业相符、教育学（A0401）须为语文/数学/英语/物理方向）。聘用：获聘人员为事业单位编制人员，享受国家及省政策规定的薪酬待遇。",
