  "exam": "网络报名—网络资格初审及确定入围面试人员—面试（现场面试考核：道德与法治、语文、数学、英语、物理、历史、生物、心理健康教育等学科专任教师岗位采用试讲形式，满分100分；体育与健康、信息技术、音乐、美术等学科专任教师岗位采用试讲+专业技能测试形式，满分100分；校医岗位采用面试答辩+专业技能测试形式，满分100分；面试成绩合格分数线统一为70分，未达合格线不能列为体检及政审对象）—资格复审—体检和政审—公示",
  "condition": "入库对象：（一）普通高等院校2026年应届毕业生；（二）社会上具有国家承认学历学位的人员。基本条件：具有中华人民共和国国籍；遵守中华人民共和国宪法和法律，无犯罪记录；具备良好的品行和职业道德；具备适应岗位要求的身体条件；具备入库公告要求的其他条件。资格条件：1.具有相应或以上层次（任教学段和任教学科）教师资格（校医岗位为具有医师或护士资格证）；暂未取得教师资格证的2026年应届毕业生可持有效期内的中小学教师资格考试合格证明或毕业院校出具的师范生教师职业能力证书报名入库，并须承诺于2026年12月31日前取得相应或以上层次的教师资格证；2.具有大学本科及以上学历；3.年龄在38周岁以下，符合以下条件之一的，可放宽至40周岁以下：（1）具有中小学中级或以上（校医岗位为卫生专业技术资格中级或以上）职称的；（2）具有研究生及以上学历的；（3）获得市级课堂教学比赛二等奖及以上的；4.所学专业与入库岗位要求的专业相对应（或相近）（详见附件1）。不得报名：受过刑事处罚的；被开除中国共产党党籍的；被开除公职的；被依法列为失信联合惩戒对象的；法律、法规规定的其他情形。库内管理：入库教师实行动态管理，入库有效期为一年，可连续报名入库；对违反师德师风、教学质量差、家长学生评价低、不服从管理等情况的教师，将其从库中移除。",
