  "condition": "招录对象：面向全社会公开招录，招录范围包含社会在职从业人员、2026届普通高校应届毕业生。基础报考条件：政治立场端正，拥护中华人民共和国宪法，遵守国家法律法规，政治品行良好；恪守《新时代中小学教师职业行为十项准则》，师德师风优良，无师德失范处分、信访追责记录；热爱基础教育事业，恪守育人初心，具备报考学科对应教学专业素养、课堂授课能力；身心健康，无传染性疾病、精神类疾病，能够全面履行教育教学、班级管理、值守育人全岗位职责。岗位准入资格：1.教师资格——须持有对应学段及以上学段的教师资格证书；2026届应届毕业生暂未取得教师资格证的，可凭有效期内《中小学教师资格考试合格证明》、师范生《教师职业能力合格证书》先行报考，2027年9月前须取得对应资质材料，逾期未取证取消聘用资格。2.学历专业要求——所有报考人员须具备本科及以上学历（幼儿园大专以上）；其中2026届应届毕业生须为全日制普通本科毕业，同步取得学士学位证书；报考合同制教师岗位人员，所学专业原则上须与报考教学学科对口匹配，专业不完全匹配人员满足以下任一条件亦可报考：①近五年获得镇级及以上教育主管部门评定教学竞赛奖项、教书育人综合荣誉；②持有报考学科中级及以上专业技术职称；③具备报考学科1年及以上一线教学工作经历（可提供劳动合同和社保缴费流水或任教学校履职证明佐证）。3.报考年龄限制——报考人员年龄原则要求40周岁及以下（计算截止日期：2026年8月31日）。",
