  "condition": "招聘对象：2026届普通高校应届毕业生，以及持有国家承认学历学位的社会人员；符合相关管理办法规定的港澳居民可报考；中山市生源公费师范生可放宽学历学位要求，所学专业须与岗位一致。薪资待遇：录用人员纳入事业单位编制，按国家及广东省统一政策享受对应薪酬福利。报考基本条件：具有中华人民共和国国籍；遵纪守法，恪守宪法与法律；拥护党的领导与社会主义制度；政治素养良好，品行端正；身体条件适配岗位工作需求；满足公告及岗位其余限定条件。不得报考情形：曾受过刑事处罚人员；被开除党籍人员；被开除公职人员；列入失信联合惩戒名单人员；法律法规明确禁止报考的其他人员。报名所需材料：填写并签字上传招聘系统内招聘人员报名表；提交身份证、学历学位证；应届生提供学生证及就业推荐表；海外学历需提供学历学位认证相关材料；有工作经历要求岗位提交工作经历佐证材料；岗位所需各类资格证书；在编在岗人员出具单位同意报考证明。报名规则：同一考点仅限报考一个岗位，多报无效；应届生须在规定时间内取得毕业证、学位证，海外学历按时完成认证；专业报考严格参照当地公务员专业参考目录执行。资格初审：报名结束后统一开展线上资格审核。准考证打印：初审通过人员可在报名结束次日21点后登录系统自行打印。",
